INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ClYYvXXG2i1', 4, '{"title":"第149条・辨太阳病脉证并治（下）第七","description":"<p>149、伤寒五六日。呕而发热者。$f{柴胡汤}证具。而以他药下之。$u{柴胡}证仍在者。复与$f{柴胡汤}。$a{此虽已下之。不为逆。}必蒸蒸而振。却发热汗出而解。若心下满而硬痛者。$a{此为结胸也。}$f{大陷胸汤}主之。但满而不痛者。$a{此为痞。}柴胡不中与之。宜$f{半夏泻心汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":149,"note":"","videoMemo":"","fangList":["柴胡汤","大陷胸汤","半夏泻心汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '149、伤寒五六日。呕而发热者。$f{柴胡汤}证具。而以他药下之。$u{柴胡}证仍在者。复与$f{柴胡汤}。$a{此虽已下之。不为逆。}必蒸蒸而振。却发热汗出而解。若心下满而硬痛者。$a{此为结胸也。}$f{大陷胸汤}主之。但满而不痛者。$a{此为痞。}柴胡不中与之。宜$f{半夏泻心汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UN5bFg5XjB7', 4, '{"title":"第150条・辨太阳病脉证并治（下）第七","description":"<p>150、太阳少阳并病。而反下之。成结胸。心下硬。下利不止。水浆不下。其人心烦。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":150,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '150、太阳少阳并病。而反下之。成结胸。心下硬。下利不止。水浆不下。其人心烦。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KnioYDLmBmF', 4, '{"title":"第151条・辨太阳病脉证并治（下）第七","description":"<p>151、脉浮而紧。而复下之。紧反入里则作痞。按之自濡。但气痞耳。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":151,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '151、脉浮而紧。而复下之。紧反入里则作痞。按之自濡。但气痞耳。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7GeR364XQFB', 4, '{"title":"第152条・辨太阳病脉证并治（下）第七","description":"<p>152、太阳中风。下利呕逆。$a{表解者。乃可攻之。}其人漐漐汗出。发作有时。头痛。心下痞硬满。引胁下痛。干呕短气。汗出不恶寒者。$a{此表解里未和也。}$f{十枣汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":152,"note":"","videoMemo":"","fangList":["十枣汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '152、太阳中风。下利呕逆。$a{表解者。乃可攻之。}其人漐漐汗出。发作有时。头痛。心下痞硬满。引胁下痛。干呕短气。汗出不恶寒者。$a{此表解里未和也。}$f{十枣汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Exi3uRe4RuL', 4, '{"title":"第153条・辨太阳病脉证并治（下）第七","description":"<p>153、太阳病。医发汗。遂发热恶寒。因复下之。心下痞。$a{表里俱虚。阴阳气并竭。无阳则阴独。}复加烧针。因胸烦。$a{面色青黄。肤瞤瞤者。难治。今色微黄。手足温者易愈。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":153,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '153、太阳病。医发汗。遂发热恶寒。因复下之。心下痞。$a{表里俱虚。阴阳气并竭。无阳则阴独。}复加烧针。因胸烦。$a{面色青黄。肤瞤瞤者。难治。今色微黄。手足温者易愈。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wS4uM3JqQAs', 4, '{"title":"第154条・辨太阳病脉证并治（下）第七","description":"<p>154、心下痞。按之濡。其脉$a{关上}浮者。$f{大黄黄连泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":154,"note":"","videoMemo":"","fangList":["大黄黄连泻心汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '154、心下痞。按之濡。其脉$a{关上}浮者。$f{大黄黄连泻心汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W0pGOrKog5d', 4, '{"title":"第155条・辨太阳病脉证并治（下）第七","description":"<p>155、心下痞。而复恶寒汗出者。$f{附子泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":155,"note":"","videoMemo":"","fangList":["附子泻心汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '155、心下痞。而复恶寒汗出者。$f{附子泻心汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fyDZhvO1tQy', 4, '{"title":"第156条・辨太阳病脉证并治（下）第七","description":"<p>156、$a{本以下之故。}心下痞。与$f{泻心汤}。痞不解。其人渴而口燥。烦。小便不利者。$f{五苓散}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":156,"note":"","videoMemo":"","fangList":["泻心汤","五苓散"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '156、$a{本以下之故。}心下痞。与$f{泻心汤}。痞不解。其人渴而口燥。烦。小便不利者。$f{五苓散}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qP29rm5i8g7', 4, '{"title":"第157条・辨太阳病脉证并治（下）第七","description":"<p>157、伤寒汗出。解之后。胃中不和。心下痞硬。干噫食臭。胁下有水气。腹中雷鸣。下利者。$f{生姜泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":157,"note":"","videoMemo":"","fangList":["生姜泻心汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '157、伤寒汗出。解之后。胃中不和。心下痞硬。干噫食臭。胁下有水气。腹中雷鸣。下利者。$f{生姜泻心汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3lHGIM7Uuvm', 4, '{"title":"第158条・辨太阳病脉证并治（下）第七","description":"<p>158、伤寒中风。医反下之。其人下利日数十行。谷不化。腹中雷鸣。心下痞硬而满。干呕。心烦不得安。医见心下痞。谓病不尽。复下之。其痞益甚。$a{此非结热。但以胃中虚。客气上逆。故使硬也。}$f{甘草泻心汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":158,"note":"","videoMemo":"","fangList":["甘草泻心汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '158、伤寒中风。医反下之。其人下利日数十行。谷不化。腹中雷鸣。心下痞硬而满。干呕。心烦不得安。医见心下痞。谓病不尽。复下之。其痞益甚。$a{此非结热。但以胃中虚。客气上逆。故使硬也。}$f{甘草泻心汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gd0oq20y1Ms', 4, '{"title":"第159条・辨太阳病脉证并治（下）第七","description":"<p>159、伤寒。服汤药。下利不止。心下痞硬。服泻心汤已。复以他药下之。利不止。医以理中与之。利益甚。$a{理中者。理中焦。此利在下焦。}$f{赤石脂禹余粮汤}主之。$a{复不止者。当利其小便。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":159,"note":"","videoMemo":"","fangList":["赤石脂禹余粮汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '159、伤寒。服汤药。下利不止。心下痞硬。服泻心汤已。复以他药下之。利不止。医以理中与之。利益甚。$a{理中者。理中焦。此利在下焦。}$f{赤石脂禹余粮汤}主之。$a{复不止者。当利其小便。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pshisUszxGy', 4, '{"title":"第160条・辨太阳病脉证并治（下）第七","description":"<p>160、伤寒吐下后。发汗。虚烦。脉甚微。八九日心下痞硬。胁下痛。气上冲咽喉。眩冒。经脉动惕者。久而成痿。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":160,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '160、伤寒吐下后。发汗。虚烦。脉甚微。八九日心下痞硬。胁下痛。气上冲咽喉。眩冒。经脉动惕者。久而成痿。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bHzYAdR27fp', 4, '{"title":"第161条・辨太阳病脉证并治（下）第七","description":"<p>161、伤寒发汗。若吐。若下。解后。心下痞硬。噫气不除者。$f{旋覆代赭汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":161,"note":"","videoMemo":"","fangList":["旋覆代赭汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '161、伤寒发汗。若吐。若下。解后。心下痞硬。噫气不除者。$f{旋覆代赭汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2XIrwceCmYe', 4, '{"title":"第162条・辨太阳病脉证并治（下）第七","description":"<p>162、下后。不可更行$f{桂枝汤}。若汗出而喘。无大热者。可与$f{麻黄杏仁甘草石膏汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":162,"note":"","videoMemo":"","fangList":["桂枝汤","麻黄杏仁甘草石膏汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '162、下后。不可更行$f{桂枝汤}。若汗出而喘。无大热者。可与$f{麻黄杏仁甘草石膏汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5KhgMRHs91T', 4, '{"title":"第163条・辨太阳病脉证并治（下）第七","description":"<p>163、太阳病。外证未除。而数下之。遂协热而利。利下不止。心下痞硬。表里不解者。$f{桂枝人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":163,"note":"","videoMemo":"","fangList":["桂枝人参汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '163、太阳病。外证未除。而数下之。遂协热而利。利下不止。心下痞硬。表里不解者。$f{桂枝人参汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('24CspqIZaIG', 4, '{"title":"第164条・辨太阳病脉证并治（下）第七","description":"<p>164、伤寒大下后。复发汗。心下痞。恶寒者。$a{表未解也。}不可攻痞。当先解表。表解乃可攻痞。$a{解表。宜$f{桂枝汤}。攻痞。宜$f{大黄黄连泻心汤}。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":164,"note":"","videoMemo":"","fangList":["桂枝汤","大黄黄连泻心汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '164、伤寒大下后。复发汗。心下痞。恶寒者。$a{表未解也。}不可攻痞。当先解表。表解乃可攻痞。$a{解表。宜$f{桂枝汤}。攻痞。宜$f{大黄黄连泻心汤}。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OTXuLKtml4o', 4, '{"title":"第165条・辨太阳病脉证并治（下）第七","description":"<p>165、伤寒发热。汗出不解。心中痞硬。呕吐而下利者。$f{大柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":165,"note":"","videoMemo":"","fangList":["大柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '165、伤寒发热。汗出不解。心中痞硬。呕吐而下利者。$f{大柴胡汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xl4b8ew5kmP', 4, '{"title":"第166条・辨太阳病脉证并治（下）第七","description":"<p>166、病如桂枝证。头不痛。项不强。寸脉微浮。胸中痞硬。气上冲喉咽不得息者。$a{此为胸有寒也。}当吐之。宜$f{瓜蒂散}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":166,"note":"","videoMemo":"","fangList":["瓜蒂散"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '166、病如桂枝证。头不痛。项不强。寸脉微浮。胸中痞硬。气上冲喉咽不得息者。$a{此为胸有寒也。}当吐之。宜$f{瓜蒂散}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8hyX0DrdiOH', 4, '{"title":"第167条・辨太阳病脉证并治（下）第七","description":"<p>167、病胁下素有痞。连在脐旁。痛引少腹。入阴筋者。此名藏结。死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":167,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '167、病胁下素有痞。连在脐旁。痛引少腹。入阴筋者。此名藏结。死。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a3G6CLWkbJY', 4, '{"title":"第168条・辨太阳病脉证并治（下）第七","description":"<p>168、伤寒。若吐、若下后。七八日不解。$a{热结在里。}表里俱热。时时恶风。大渴。舌上干燥而烦。欲饮水数升者。$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":168,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '168、伤寒。若吐、若下后。七八日不解。$a{热结在里。}表里俱热。时时恶风。大渴。舌上干燥而烦。欲饮水数升者。$f{白虎加人参汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ytIwubNjfgT', 4, '{"title":"第169条・辨太阳病脉证并治（下）第七","description":"<p>169、伤寒。无大热。口燥渴。心烦。背微恶寒者。$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":169,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '169、伤寒。无大热。口燥渴。心烦。背微恶寒者。$f{白虎加人参汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H0Htb35n9ie', 4, '{"title":"第170条・辨太阳病脉证并治（下）第七","description":"<p>170、伤寒。脉浮。发热无汗。$a{其表不解。不可与$f{白虎汤}。}渴欲饮水。无表证者。$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":170,"note":"","videoMemo":"","fangList":["白虎汤","白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '170、伤寒。脉浮。发热无汗。$a{其表不解。不可与$f{白虎汤}。}渴欲饮水。无表证者。$f{白虎加人参汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RAvNxsSy2Pi', 4, '{"title":"第171条・辨太阳病脉证并治（下）第七","description":"<p>171、太阳少阳并病。心下硬。颈项强而眩者。当刺大椎、肺俞、肝俞。慎勿下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":171,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '171、太阳少阳并病。心下硬。颈项强而眩者。当刺大椎、肺俞、肝俞。慎勿下之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hoF5B3yEwhc', 4, '{"title":"第172条・辨太阳病脉证并治（下）第七","description":"<p>172、太阳与少阳合病。自下利者。与$f{黄芩汤}。若呕者。$f{黄芩加半夏生姜汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":172,"note":"","videoMemo":"","fangList":["黄芩汤","黄芩加半夏生姜汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '172、太阳与少阳合病。自下利者。与$f{黄芩汤}。若呕者。$f{黄芩加半夏生姜汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z54xf0Dx81U', 4, '{"title":"第173条・辨太阳病脉证并治（下）第七","description":"<p>173、伤寒。胸中有热。胃中有邪气。腹中痛。欲呕吐者。$f{黄连汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":173,"note":"","videoMemo":"","fangList":["黄连汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '173、伤寒。胸中有热。胃中有邪气。腹中痛。欲呕吐者。$f{黄连汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('75pnmhLprJ1', 4, '{"title":"第174条・辨太阳病脉证并治（下）第七","description":"<p>174、伤寒八九日。风湿相搏。身体疼烦。不能自转侧。不呕不渴。脉浮虚而涩者。$f{桂枝附子汤}主之。若其人大便硬。$a{脐下心下硬。}小便自利者$a{（康平本做“不利“）}。$f{去桂加白术汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":174,"note":"","videoMemo":"","fangList":["桂枝附子汤","去桂加白术汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '174、伤寒八九日。风湿相搏。身体疼烦。不能自转侧。不呕不渴。脉浮虚而涩者。$f{桂枝附子汤}主之。若其人大便硬。$a{脐下心下硬。}小便自利者$a{（康平本做“不利“）}。$f{去桂加白术汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dVRz7YeulcN', 4, '{"title":"第175条・辨太阳病脉证并治（下）第七","description":"<p>175、风湿相搏。骨节疼烦。掣痛不得屈伸。近之则痛剧。汗出短气。小便不利。恶风不欲去衣。或身微肿者。$f{甘草附子汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":175,"note":"","videoMemo":"","fangList":["甘草附子汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '175、风湿相搏。骨节疼烦。掣痛不得屈伸。近之则痛剧。汗出短气。小便不利。恶风不欲去衣。或身微肿者。$f{甘草附子汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7rDwD5Cc3qT', 4, '{"title":"第176条・辨太阳病脉证并治（下）第七","description":"<p>176、伤寒。脉浮滑。$a{此以表有热。里有寒。}$f{白虎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":176,"note":"","videoMemo":"","fangList":["白虎汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '176、伤寒。脉浮滑。$a{此以表有热。里有寒。}$f{白虎汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2teb4WY701T', 4, '{"title":"第177条・辨太阳病脉证并治（下）第七","description":"<p>177、伤寒。脉结代。心动悸。$f{炙甘草汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":177,"note":"","videoMemo":"","fangList":["炙甘草汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '177、伤寒。脉结代。心动悸。$f{炙甘草汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q1Wr0eYjA36', 4, '{"title":"第178条・辨太阳病脉证并治（下）第七","description":"<p>178、脉按之来缓。时一止复来者。名曰结。又脉来动而中止。更来小数。中有还者反动。名曰结。阴也。脉来动而中止。不能自还。因而复动者。名曰代。阴也。得此脉者。必难治。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":178,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '178、脉按之来缓。时一止复来者。名曰结。又脉来动而中止。更来小数。中有还者反动。名曰结。阴也。脉来动而中止。不能自还。因而复动者。名曰代。阴也。得此脉者。必难治。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'KeDfn7xcG3W');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e8jDclZcf8r', 4, '{"title":"第179条・辨阳明病脉证并治第八","description":"<p>179、问曰：病有太阳阳明。有正阳阳明。有少阳阳明。何谓也？答曰：太阳阳明者。脾约是也。正阳阳明者。胃家实是也。少阳阳明者。发汗利小便已。胃中燥烦实。大便难是也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":179,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '179、问曰：病有太阳阳明。有正阳阳明。有少阳阳明。何谓也？答曰：太阳阳明者。脾约是也。正阳阳明者。胃家实是也。少阳阳明者。发汗利小便已。胃中燥烦实。大便难是也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9UMWVDED9Ge', 4, '{"title":"第180条・辨阳明病脉证并治第八","description":"<p>180、阳明之为病。胃家实$a{（一作寒）}是也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":180,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '180、阳明之为病。胃家实$a{（一作寒）}是也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t1a08u1SDVH', 4, '{"title":"第181条・辨阳明病脉证并治第八","description":"<p>181、问曰：何缘得阳明病？答曰：太阳病。若发汗。若下。若利小便。此亡津液。胃中干燥。因转属阳明。不更衣。内实。大便难者。此名阳明也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":181,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '181、问曰：何缘得阳明病？答曰：太阳病。若发汗。若下。若利小便。此亡津液。胃中干燥。因转属阳明。不更衣。内实。大便难者。此名阳明也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('55T4VBRJKAN', 4, '{"title":"第182条・辨阳明病脉证并治第八","description":"<p>182、问曰：阳明病外证云何？答曰：身热。汗自出。不恶寒反恶热也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":182,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '182、问曰：阳明病外证云何？答曰：身热。汗自出。不恶寒反恶热也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GbVCMVabIgq', 4, '{"title":"第183条・辨阳明病脉证并治第八","description":"<p>183、问曰：病有得之一日。不发热而恶寒者。何也？答曰：虽得之一日。恶寒将自罢。即自汗出而恶热也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":183,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '183、问曰：病有得之一日。不发热而恶寒者。何也？答曰：虽得之一日。恶寒将自罢。即自汗出而恶热也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mclJTbiHuql', 4, '{"title":"第184条・辨阳明病脉证并治第八","description":"<p>184、问曰：恶寒何故自罢？答曰：阳明居中主土也。万物所归。无所复传。始虽恶寒。二日自止。此为阳明病也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":184,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '184、问曰：恶寒何故自罢？答曰：阳明居中主土也。万物所归。无所复传。始虽恶寒。二日自止。此为阳明病也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fFGFby8myFt', 4, '{"title":"第185条・辨阳明病脉证并治第八","description":"<p>185、本太阳。初得病时。发其汗。汗先出不彻。因转属阳明也。伤寒发热无汗。呕不能食。而反汗出濈濈然者。是转属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":185,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '185、本太阳。初得病时。发其汗。汗先出不彻。因转属阳明也。伤寒发热无汗。呕不能食。而反汗出濈濈然者。是转属阳明也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fWrAw8wpccb', 4, '{"title":"第186条・辨阳明病脉证并治第八","description":"<p>186、伤寒三日。阳明脉大。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":186,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '186、伤寒三日。阳明脉大。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YqosYc0DdGn', 4, '{"title":"第187条・辨阳明病脉证并治第八","description":"<p>187、伤寒脉浮而缓。手足自温者。是为系在太阴。太阴者。身当发黄。若小便自利者。不能发黄。至七八日。大便硬者。为阳明病也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":187,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '187、伤寒脉浮而缓。手足自温者。是为系在太阴。太阴者。身当发黄。若小便自利者。不能发黄。至七八日。大便硬者。为阳明病也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qj3oj5p1sy3', 4, '{"title":"第188条・辨阳明病脉证并治第八","description":"<p>188、伤寒转系阳明者。其人濈然微汗出也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":188,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '188、伤寒转系阳明者。其人濈然微汗出也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QS5k5o19hzD', 4, '{"title":"第189条・辨阳明病脉证并治第八","description":"<p>189、阳明中风。口苦咽干。腹满微喘。发热恶寒。脉浮而紧。若下之。则腹满。小便难也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":189,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '189、阳明中风。口苦咽干。腹满微喘。发热恶寒。脉浮而紧。若下之。则腹满。小便难也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QkhhsJqJFnf', 4, '{"title":"第190条・辨阳明病脉证并治第八","description":"<p>190、阳明病。若能食。名中风。不能食。名中寒。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":190,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '190、阳明病。若能食。名中风。不能食。名中寒。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NMiAunJHVgs', 4, '{"title":"第191条・辨阳明病脉证并治第八","description":"<p>191、阳明病。若中寒者。不能食。小便不利。手足濈然汗出。$a{此欲作固瘕。}必大便初硬后溏。$a{所以然者。以胃中冷。水谷不别故也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":191,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '191、阳明病。若中寒者。不能食。小便不利。手足濈然汗出。$a{此欲作固瘕。}必大便初硬后溏。$a{所以然者。以胃中冷。水谷不别故也。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SgVE8Vap5Z2', 4, '{"title":"第192条・辨阳明病脉证并治第八","description":"<p>192、阳明病。初欲食。小便反不利。大便自调。其人骨节疼。翕翕如有热状。奄然发狂。濈然汗出而解。$a{汗出而解者。此水不胜谷气。与汗共并。脉紧则愈。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":192,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '192、阳明病。初欲食。小便反不利。大便自调。其人骨节疼。翕翕如有热状。奄然发狂。濈然汗出而解。$a{汗出而解者。此水不胜谷气。与汗共并。脉紧则愈。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ybyanA0VH4V', 4, '{"title":"第193条・辨阳明病脉证并治第八","description":"<p>193、阳明病。欲解时。从申至戌上。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":193,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '193、阳明病。欲解时。从申至戌上。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nOs4O4vGzLa', 4, '{"title":"第194条・辨阳明病脉证并治第八","description":"<p>194、阳明病。不能食。攻其热必哕。$a{所以然者。胃中虚冷故也。以其人本虚。攻其热必哕。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":194,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '194、阳明病。不能食。攻其热必哕。$a{所以然者。胃中虚冷故也。以其人本虚。攻其热必哕。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LcT6g31EIzl', 4, '{"title":"第195条・辨阳明病脉证并治第八","description":"<p>195、阳明病。脉迟。食难用饱。饱则微烦头眩。必小便难。$a{此欲作谷瘅。}虽下之。腹满如故。$a{所以然者。脉迟故也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":195,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '195、阳明病。脉迟。食难用饱。饱则微烦头眩。必小便难。$a{此欲作谷瘅。}虽下之。腹满如故。$a{所以然者。脉迟故也。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h7zL2rpMnXW', 4, '{"title":"第196条・辨阳明病脉证并治第八","description":"<p>196、阳明病。法多汗。反无汗。其身如虫行皮中状者。此以久虚故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":196,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '196、阳明病。法多汗。反无汗。其身如虫行皮中状者。此以久虚故也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U8u9tMxDJQm', 4, '{"title":"第197条・辨阳明病脉证并治第八","description":"<p>197、$a{冬}阳明病。反无汗。而小便利。二三日呕而咳。手足厥者。必苦头痛。若不咳。不呕。手足不厥者。头不痛。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":197,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '197、$a{冬}阳明病。反无汗。而小便利。二三日呕而咳。手足厥者。必苦头痛。若不咳。不呕。手足不厥者。头不痛。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0diMRRoipsp', 4, '{"title":"第198条・辨阳明病脉证并治第八","description":"<p>198、$a{冬}阳明病。但头眩。不恶寒。故能食而咳。其人咽必痛。若不咳者。咽不痛。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":198,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '198、$a{冬}阳明病。但头眩。不恶寒。故能食而咳。其人咽必痛。若不咳者。咽不痛。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3eBPX1xNaW5', 4, '{"title":"第199条・辨阳明病脉证并治第八","description":"<p>199、阳明病无汗。小便不利。心中懊憹者。身必发黄。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":199,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '199、阳明病无汗。小便不利。心中懊憹者。身必发黄。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Qc1vgCKQks3', 4, '{"title":"第200条・辨阳明病脉证并治第八","description":"<p>200、阳明病。被火。额上微汗出而小便不利者。必发黄。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":200,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '200、阳明病。被火。额上微汗出而小便不利者。必发黄。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y61MfLzBLw1', 4, '{"title":"第201条・辨阳明病脉证并治第八","description":"<p>201、阳明病。脉浮而紧者。必潮热。发作有时。但浮者。必盗汗出。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '201、阳明病。脉浮而紧者。必潮热。发作有时。但浮者。必盗汗出。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S8Jn9hG8kc9', 4, '{"title":"第202条・辨阳明病脉证并治第八","description":"<p>202、阳明病。口燥。但欲漱水不欲咽者。此必衄。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":202,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '202、阳明病。口燥。但欲漱水不欲咽者。此必衄。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UJFFGNdqax7', 4, '{"title":"第203条・辨阳明病脉证并治第八","description":"<p>203、阳明病。本自汗出。医更重发汗。病已差。尚微烦不了了者。$a{此必大便硬故也。}以亡津液。胃中干燥。故令大便硬。$a{当问其小便日几行。若本小便日三四行。今日再行。故知大便不久出。今为小便数少。以津液当还入胃中。故知不久必大便也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":203,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '203、阳明病。本自汗出。医更重发汗。病已差。尚微烦不了了者。$a{此必大便硬故也。}以亡津液。胃中干燥。故令大便硬。$a{当问其小便日几行。若本小便日三四行。今日再行。故知大便不久出。今为小便数少。以津液当还入胃中。故知不久必大便也。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lfSRrxX7HGo', 4, '{"title":"第204条・辨阳明病脉证并治第八","description":"<p>204、伤寒呕多。虽有阳明证。不可攻之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":204,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '204、伤寒呕多。虽有阳明证。不可攻之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Awk6KAzmjHw', 4, '{"title":"第205条・辨阳明病脉证并治第八","description":"<p>205、阳明病。心下硬满者。不可攻之。攻之利遂不止者死。利止者愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":205,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '205、阳明病。心下硬满者。不可攻之。攻之利遂不止者死。利止者愈。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BYKKfYAAc6V', 4, '{"title":"第206条・辨阳明病脉证并治第八","description":"<p>206、阳明病。面合色赤。不可攻之。必发热。色黄者。小便不利也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":206,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '206、阳明病。面合色赤。不可攻之。必发热。色黄者。小便不利也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('foBCl71hFjB', 4, '{"title":"第207条・辨阳明病脉证并治第八","description":"<p>207、阳明病。不吐不下。心烦者。可与$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":207,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '207、阳明病。不吐不下。心烦者。可与$f{调胃承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6FMSm6uPQlE', 4, '{"title":"第208条・辨阳明病脉证并治第八","description":"<p>208、阳明病。脉迟。虽汗出。不恶寒者。其身必重。短气。腹满而喘。有潮热。$a{有潮热者。此外欲解。可攻里也。}手足濈然汗出者。$a{此大便已硬也。}$f{大承气汤}主之。若汗多。微发热恶寒者。外未解也。其热不潮。未可与承气汤。若腹大满不通者。可与$f{小承气汤}微和胃气。勿令至大泄下。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":208,"note":"","videoMemo":"","fangList":["大承气汤","小承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '208、阳明病。脉迟。虽汗出。不恶寒者。其身必重。短气。腹满而喘。有潮热。$a{有潮热者。此外欲解。可攻里也。}手足濈然汗出者。$a{此大便已硬也。}$f{大承气汤}主之。若汗多。微发热恶寒者。外未解也。其热不潮。未可与承气汤。若腹大满不通者。可与$f{小承气汤}微和胃气。勿令至大泄下。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hUrmRaaJCQl', 4, '{"title":"第209条・辨阳明病脉证并治第八","description":"<p>209、阳明病。潮热。大便微硬者。可与$f{大承气汤}。$a{不硬者。不可与之。}若不大便六七日。恐有燥屎。欲知之法。少与$f{小承气汤}。汤入腹中。转矢气者。此有燥屎也。乃可攻之。若不转矢气者。此但初头硬。后必溏。不可攻之。攻之必胀满不能食也。欲饮水者。与水则哕。其后发热者。必大便复硬而少也。以$f{小承气汤}和之。不转矢气者。慎不可攻也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":209,"note":"","videoMemo":"","fangList":["大承气汤","小承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '209、阳明病。潮热。大便微硬者。可与$f{大承气汤}。$a{不硬者。不可与之。}若不大便六七日。恐有燥屎。欲知之法。少与$f{小承气汤}。汤入腹中。转矢气者。此有燥屎也。乃可攻之。若不转矢气者。此但初头硬。后必溏。不可攻之。攻之必胀满不能食也。欲饮水者。与水则哕。其后发热者。必大便复硬而少也。以$f{小承气汤}和之。不转矢气者。慎不可攻也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YsU3OHJno1y', 4, '{"title":"第210条・辨阳明病脉证并治第八","description":"<p>210、夫实则谵语。虚则郑声。$a{郑声者。重语也。}直视谵语。喘满者死。下利者亦死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":210,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '210、夫实则谵语。虚则郑声。$a{郑声者。重语也。}直视谵语。喘满者死。下利者亦死。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7ykYCp4lyVY', 4, '{"title":"第211条・辨阳明病脉证并治第八","description":"<p>211、发汗多。若重发汗者。亡其阳。谵语。脉短者死。脉自和者不死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":211,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '211、发汗多。若重发汗者。亡其阳。谵语。脉短者死。脉自和者不死。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nFq9pk9BldQ', 4, '{"title":"第212条・辨阳明病脉证并治第八","description":"<p>212、伤寒。若吐若下后。不解。不大便五六日。上至十余日。日晡所发潮热。不恶寒。独语如见鬼状。若剧者。发则不识人。循衣摸床。惕而不安。微喘直视。$a{脉弦者生。涩者死。微者。但发热。}谵语者。$f{大承气汤}主之。$a{若一服利。则止后服。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":212,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '212、伤寒。若吐若下后。不解。不大便五六日。上至十余日。日晡所发潮热。不恶寒。独语如见鬼状。若剧者。发则不识人。循衣摸床。惕而不安。微喘直视。$a{脉弦者生。涩者死。微者。但发热。}谵语者。$f{大承气汤}主之。$a{若一服利。则止后服。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TUAXeYiFOts', 4, '{"title":"第213条・辨阳明病脉证并治第八","description":"<p>213、阳明病。其人多汗。以津液外出。胃中燥。大便必硬。硬则谵语。$f{小承气汤}主之。若一服谵语止者。更莫复服。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":213,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '213、阳明病。其人多汗。以津液外出。胃中燥。大便必硬。硬则谵语。$f{小承气汤}主之。若一服谵语止者。更莫复服。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fgzGeEworF8', 4, '{"title":"第214条・辨阳明病脉证并治第八","description":"<p>214、阳明病。谵语。发潮热。脉滑而疾者。$f{小承气汤}主之。因与承气汤一升。腹中转气者。更服一升。若不转气者。勿更与之。明日又不大便。脉反微涩者。里虚也。为难治。不可更与承气汤也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":214,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '214、阳明病。谵语。发潮热。脉滑而疾者。$f{小承气汤}主之。因与承气汤一升。腹中转气者。更服一升。若不转气者。勿更与之。明日又不大便。脉反微涩者。里虚也。为难治。不可更与承气汤也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Wslt22wWIZ', 4, '{"title":"第215条・辨阳明病脉证并治第八","description":"<p>215、阳明病。谵语。有潮热。反不能食者。胃中必有燥屎五六枚也。若能食者。但硬耳。宜$f{大承气汤}下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":215,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '215、阳明病。谵语。有潮热。反不能食者。胃中必有燥屎五六枚也。若能食者。但硬耳。宜$f{大承气汤}下之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GfVh6Fn27zZ', 4, '{"title":"第216条・辨阳明病脉证并治第八","description":"<p>216、阳明病。下血谵语者。此为热入血室。但头汗出者。刺期门。随其实而泻之。濈然汗出则愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":216,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '216、阳明病。下血谵语者。此为热入血室。但头汗出者。刺期门。随其实而泻之。濈然汗出则愈。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HscW1EjuE93', 4, '{"title":"第217条・辨阳明病脉证并治第八","description":"<p>217、汗出谵语者。以有燥屎在胃中$a{（此为风）}也。须下者。过经乃可下之。下之若早。语言必乱。以表虚里实故也。$a{下之愈。}宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":217,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '217、汗出谵语者。以有燥屎在胃中$a{（此为风）}也。须下者。过经乃可下之。下之若早。语言必乱。以表虚里实故也。$a{下之愈。}宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i4Pw3BfG50v', 4, '{"title":"第218条・辨阳明病脉证并治第八","description":"<p>218、伤寒四五日。脉沉而喘满。$a{沉为在里。}而反发其汗。津液越出。大便为难。表虚里实。久则谵语。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":218,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '218、伤寒四五日。脉沉而喘满。$a{沉为在里。}而反发其汗。津液越出。大便为难。表虚里实。久则谵语。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QM97fCJza7i', 4, '{"title":"第219条・辨阳明病脉证并治第八","description":"<p>219、三阳合病。腹满身重。难于转侧。口不仁面垢。谵语遗尿。发汗则谵语。下之则额上生汗。手足逆冷。若自汗出者。$f{白虎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":219,"note":"","videoMemo":"","fangList":["白虎汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '219、三阳合病。腹满身重。难于转侧。口不仁面垢。谵语遗尿。发汗则谵语。下之则额上生汗。手足逆冷。若自汗出者。$f{白虎汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NAEozg9D8xe', 4, '{"title":"第220条・辨阳明病脉证并治第八","description":"<p>220、二阳并病。太阳证罢。但发潮热。手足漐漐汗出。大便难而谵语者。下之则愈。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":220,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '220、二阳并病。太阳证罢。但发潮热。手足漐漐汗出。大便难而谵语者。下之则愈。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mWg8CPu09Us', 4, '{"title":"第221条・辨阳明病脉证并治第八","description":"<p>221、阳明病。脉浮而紧。咽燥口苦。腹满而喘。发热汗出。不恶寒。反恶热。身重。若发汗则躁。心愦愦反谵语。若加温针。必怵惕。烦躁不得眠。若下之。则胃中空虚。客气动膈。心中懊憹。舌上胎者。$f{栀子豉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":221,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '221、阳明病。脉浮而紧。咽燥口苦。腹满而喘。发热汗出。不恶寒。反恶热。身重。若发汗则躁。心愦愦反谵语。若加温针。必怵惕。烦躁不得眠。若下之。则胃中空虚。客气动膈。心中懊憹。舌上胎者。$f{栀子豉汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yGtoQ3OkdOi', 4, '{"title":"第222条・辨阳明病脉证并治第八","description":"<p>222、若渴欲饮水。口干舌燥者。$f{白虎加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":222,"note":"","videoMemo":"","fangList":["白虎加人参汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '222、若渴欲饮水。口干舌燥者。$f{白虎加人参汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XEDgL20jA5u', 4, '{"title":"第223条・辨阳明病脉证并治第八","description":"<p>223、若$a{（脉浮发热）}渴欲饮水。小便不利者。$f{猪苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":223,"note":"","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '223、若$a{（脉浮发热）}渴欲饮水。小便不利者。$f{猪苓汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dx6aWv8Q0M6', 4, '{"title":"第224条・辨阳明病脉证并治第八","description":"<p>224、阳明病。汗出多而渴者。不可与$f{猪苓汤}。以汗多胃中燥。$f{猪苓汤}复利其小便故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":224,"note":"","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '224、阳明病。汗出多而渴者。不可与$f{猪苓汤}。以汗多胃中燥。$f{猪苓汤}复利其小便故也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oYTYtUOcJC2', 4, '{"title":"第225条・辨阳明病脉证并治第八","description":"<p>225、脉浮而迟。表热里寒。下利清谷者。$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":225,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '225、脉浮而迟。表热里寒。下利清谷者。$f{四逆汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2Px2nI55v75', 4, '{"title":"第226条・辨阳明病脉证并治第八","description":"<p>226、若胃中虚冷。不能食者。饮水则哕。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":226,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '226、若胃中虚冷。不能食者。饮水则哕。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BhwBlgYrOrI', 4, '{"title":"第227条・辨阳明病脉证并治第八","description":"<p>227、脉浮发热。口干鼻燥。能食者则衄。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":227,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '227、脉浮发热。口干鼻燥。能食者则衄。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mmixwJk6QW4', 4, '{"title":"第228条・辨阳明病脉证并治第八","description":"<p>228、阳明病下之。其外有热。手足温。$a{不结胸$a{（康平本做“小结胸”）}。}心中懊憹。饥不能食。但头汗出者。$f{栀子豉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":228,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '228、阳明病下之。其外有热。手足温。$a{不结胸$a{（康平本做“小结胸”）}。}心中懊憹。饥不能食。但头汗出者。$f{栀子豉汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gEyDFEJfkDI', 4, '{"title":"第229条・辨阳明病脉证并治第八","description":"<p>229、阳明病。发潮热。大便溏。小便自可。胸胁满不去者。与$f{小柴胡汤}。$a{（康平本作“$f{柴胡汤}主之”）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":229,"note":"","videoMemo":"","fangList":["小柴胡汤","柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '229、阳明病。发潮热。大便溏。小便自可。胸胁满不去者。与$f{小柴胡汤}。$a{（康平本作“$f{柴胡汤}主之”）}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('93gXyljzpqU', 4, '{"title":"第230条・辨阳明病脉证并治第八","description":"<p>230、阳明病。胁下硬满。不大便而呕。舌上白胎者。可与$f{小柴胡汤}。上焦得通。津液得下。胃气因和。身濈然汗出而解。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":230,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '230、阳明病。胁下硬满。不大便而呕。舌上白胎者。可与$f{小柴胡汤}。上焦得通。津液得下。胃气因和。身濈然汗出而解。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('x74fIK7N6uj', 4, '{"title":"第231条・辨阳明病脉证并治第八","description":"<p>231、阳明中风。脉弦浮大。而短气。腹都满。胁下及心痛。久按之气不通。鼻干。不得汗。嗜卧。一身及目悉黄。小便难。有潮热。时时哕。耳前后肿。刺之小差。外不解。病过十日。脉续浮者。与$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":231,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '231、阳明中风。脉弦浮大。而短气。腹都满。胁下及心痛。久按之气不通。鼻干。不得汗。嗜卧。一身及目悉黄。小便难。有潮热。时时哕。耳前后肿。刺之小差。外不解。病过十日。脉续浮者。与$f{小柴胡汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QEh1Rzjt0l9', 4, '{"title":"第232条・辨阳明病脉证并治第八","description":"<p>232、脉但浮。无余证者。与$f{麻黄汤}。$a{若不尿。腹满加哕者。不治。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":232,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '232、脉但浮。无余证者。与$f{麻黄汤}。$a{若不尿。腹满加哕者。不治。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nBxlb440K9V', 4, '{"title":"第233条・辨阳明病脉证并治第八","description":"<p>233、阳明病。自汗出。若发汗。小便自利者。$a{此为津液内竭。}虽硬不可攻之。当须自欲大便。宜$f{蜜煎导}而通之。若$u{土瓜根}及$u{大猪胆汁}。皆可为导。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":233,"note":"","videoMemo":"","fangList":["蜜煎导"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '233、阳明病。自汗出。若发汗。小便自利者。$a{此为津液内竭。}虽硬不可攻之。当须自欲大便。宜$f{蜜煎导}而通之。若$u{土瓜根}及$u{大猪胆汁}。皆可为导。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sMHP0vGlS6n', 4, '{"title":"第234条・辨阳明病脉证并治第八","description":"<p>234、阳明病。脉迟。汗出多。微恶寒者。表未解也。可发汗。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":234,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '234、阳明病。脉迟。汗出多。微恶寒者。表未解也。可发汗。宜$f{桂枝汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DYcSfg1eDrI', 4, '{"title":"第235条・辨阳明病脉证并治第八","description":"<p>235、阳明病。脉浮。无汗而喘者。发汗则愈。宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":235,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '235、阳明病。脉浮。无汗而喘者。发汗则愈。宜$f{麻黄汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sbLJ0Erxnh4', 4, '{"title":"第236条・辨阳明病脉证并治第八","description":"<p>236、阳明病。发热汗出者。$a{此为热越。}不能发黄也。但头汗出。身无汗。剂颈而还。小便不利。渴引水浆者。$a{此为瘀热在里。}身必发黄。$f{茵陈蒿汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":236,"note":"","videoMemo":"","fangList":["茵陈蒿汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '236、阳明病。发热汗出者。$a{此为热越。}不能发黄也。但头汗出。身无汗。剂颈而还。小便不利。渴引水浆者。$a{此为瘀热在里。}身必发黄。$f{茵陈蒿汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sI2pcojkaor', 4, '{"title":"第237条・辨阳明病脉证并治第八","description":"<p>237、阳明证。其人喜忘者。必有蓄血。$a{所以然者。本有久瘀血。故令喜忘。}屎虽硬$a{（康平本做“尿虽难”）}。大便反易。其色必黑者。宜$f{抵当汤}下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":237,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '237、阳明证。其人喜忘者。必有蓄血。$a{所以然者。本有久瘀血。故令喜忘。}屎虽硬$a{（康平本做“尿虽难”）}。大便反易。其色必黑者。宜$f{抵当汤}下之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MeKlnjpG5KG', 4, '{"title":"第238条・辨阳明病脉证并治第八","description":"<p>238、阳明病。下之。心中懊憹而烦。胃中有燥屎者。$a{可攻。腹微满。初头硬。后必溏。不可攻之。若有燥屎者。}宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":238,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '238、阳明病。下之。心中懊憹而烦。胃中有燥屎者。$a{可攻。腹微满。初头硬。后必溏。不可攻之。若有燥屎者。}宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m0N0Zq3Gg6q', 4, '{"title":"第239条・辨阳明病脉证并治第八","description":"<p>239、病人不大便五六日。绕脐痛。烦躁。发作有时者。此有燥屎。故使不大便也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":239,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '239、病人不大便五六日。绕脐痛。烦躁。发作有时者。此有燥屎。故使不大便也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bObJPZxApQl', 4, '{"title":"第240条・辨阳明病脉证并治第八","description":"<p>240、病人烦热。汗出则解。又如疟状。日晡所发热者。属阳明也。脉实者。宜下之。脉浮虚者。宜发汗。下之。与$f{大承气汤}。发汗。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":240,"note":"","videoMemo":"","fangList":["大承气汤","桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '240、病人烦热。汗出则解。又如疟状。日晡所发热者。属阳明也。脉实者。宜下之。脉浮虚者。宜发汗。下之。与$f{大承气汤}。发汗。宜$f{桂枝汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N4JrQq1Is41', 4, '{"title":"第241条・辨阳明病脉证并治第八","description":"<p>241、大下后。六七日不大便。烦不解。腹满痛者。此有燥屎也。$a{所以然者。本有宿食故也。}宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":241,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '241、大下后。六七日不大便。烦不解。腹满痛者。此有燥屎也。$a{所以然者。本有宿食故也。}宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('479mbR7e325', 4, '{"title":"第242条・辨阳明病脉证并治第八","description":"<p>242、病人小便不利。大便乍难乍易。时有微热。喘冒$a{（一作怫郁）}不能卧者。有燥屎也。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":242,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '242、病人小便不利。大便乍难乍易。时有微热。喘冒$a{（一作怫郁）}不能卧者。有燥屎也。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YA1mucmsD2G', 4, '{"title":"第243条・辨阳明病脉证并治第八","description":"<p>243、食谷欲呕。属阳明也。$f{吴茱萸汤}主之。$a{得汤反剧者。属上焦也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":243,"note":"","videoMemo":"","fangList":["吴茱萸汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '243、食谷欲呕。属阳明也。$f{吴茱萸汤}主之。$a{得汤反剧者。属上焦也。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('drCeA5wrqU6', 4, '{"title":"第244条・辨阳明病脉证并治第八","description":"<p>244、太阳病。$a{(寸)}缓$a{(关)}浮$a{(尺)}弱。其人发热汗出。复恶寒。不呕。但心下痞者。此以医下之也。如其不下者。病人不恶寒而渴。$a{渴者。此转属阳明也。}小便数者。大便必硬。不更衣十日。无所苦也。渴欲饮水。少少与之。但以法救之。渴者。宜$f{五苓散}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":244,"note":"","videoMemo":"","fangList":["五苓散"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '244、太阳病。$a{(寸)}缓$a{(关)}浮$a{(尺)}弱。其人发热汗出。复恶寒。不呕。但心下痞者。此以医下之也。如其不下者。病人不恶寒而渴。$a{渴者。此转属阳明也。}小便数者。大便必硬。不更衣十日。无所苦也。渴欲饮水。少少与之。但以法救之。渴者。宜$f{五苓散}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F8wxt5ev7iy', 4, '{"title":"第245条・辨阳明病脉证并治第八","description":"<p>245、脉阳微而汗出少者。为自和也。汗出多者。为太过。阳脉实因发其汗。出多者。亦为太过。太过者。为阳绝于里。亡津液。大便因硬也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":245,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '245、脉阳微而汗出少者。为自和也。汗出多者。为太过。阳脉实因发其汗。出多者。亦为太过。太过者。为阳绝于里。亡津液。大便因硬也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BbaBkrrvOJD', 4, '{"title":"第246条・辨阳明病脉证并治第八","description":"<p>246、脉浮而芤。浮为阳。芤为阴。浮芤相搏。胃气生热。其阳则绝。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":246,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '246、脉浮而芤。浮为阳。芤为阴。浮芤相搏。胃气生热。其阳则绝。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q6GKlwuD2CD', 4, '{"title":"第247条・辨阳明病脉证并治第八","description":"<p>247、趺阳脉浮而涩。浮则胃气强。涩则小便数。浮涩相搏。大便则硬。其脾为约。$f{麻子仁丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":247,"note":"","videoMemo":"","fangList":["麻子仁丸"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '247、趺阳脉浮而涩。浮则胃气强。涩则小便数。浮涩相搏。大便则硬。其脾为约。$f{麻子仁丸}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HdNzv5xuOgU', 4, '{"title":"第248条・辨阳明病脉证并治第八","description":"<p>248、太阳病三日。发汗不解。蒸蒸发热者。属胃也。$f{调胃承气汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":248,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '248、太阳病三日。发汗不解。蒸蒸发热者。属胃也。$f{调胃承气汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Oc2uySTOC9', 4, '{"title":"第249条・辨阳明病脉证并治第八","description":"<p>249、伤寒吐后。腹胀满者。与$f{调胃承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":249,"note":"","videoMemo":"","fangList":["调胃承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '249、伤寒吐后。腹胀满者。与$f{调胃承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dq7xihXlpX0', 4, '{"title":"第250条・辨阳明病脉证并治第八","description":"<p>250、太阳病。若吐。若下、若发汗后。微烦。小便数。大便因硬者。与$f{小承气汤}和之愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":250,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '250、太阳病。若吐。若下、若发汗后。微烦。小便数。大便因硬者。与$f{小承气汤}和之愈。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bQlcCDPplg0', 4, '{"title":"第251条・辨阳明病脉证并治第八","description":"<p>251、得病二三日。脉弱。无太阳柴胡证。烦躁。心下硬。至四五日。虽能食。以$f{小承气汤}少少与微和之。令小安。至六日。与承气汤一升。若不大便六七日。小便少者。虽不受食。但初头硬。后必溏。未定成硬。攻之必溏。须小便利。屎定硬。乃可攻之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":251,"note":"","videoMemo":"","fangList":["小承气汤","大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '251、得病二三日。脉弱。无太阳柴胡证。烦躁。心下硬。至四五日。虽能食。以$f{小承气汤}少少与微和之。令小安。至六日。与承气汤一升。若不大便六七日。小便少者。虽不受食。但初头硬。后必溏。未定成硬。攻之必溏。须小便利。屎定硬。乃可攻之。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LMnyac95NYv', 4, '{"title":"第252条・辨阳明病脉证并治第八","description":"<p>252、伤寒六七日。目中不了了。睛不和。无表里证。大便难。身微热者。$a{此为实也。}急下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":252,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '252、伤寒六七日。目中不了了。睛不和。无表里证。大便难。身微热者。$a{此为实也。}急下之。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PvkD5uJkjgc', 4, '{"title":"第253条・辨阳明病脉证并治第八","description":"<p>253、阳明病。发热汗多者。急下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":253,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '253、阳明病。发热汗多者。急下之。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9R206jRI2nX', 4, '{"title":"第254条・辨阳明病脉证并治第八","description":"<p>254、发汗不解。腹满痛者。急下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":254,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '254、发汗不解。腹满痛者。急下之。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n6YCoIW9qcE', 4, '{"title":"第255条・辨阳明病脉证并治第八","description":"<p>255、腹满不减。减不足言。当下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":255,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '255、腹满不减。减不足言。当下之。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p3rIOpRVDfE', 4, '{"title":"第256条・辨阳明病脉证并治第八","description":"<p>256、阳明少阳合病。必下利。$a{其脉不负者。为顺也。负者。失也。互相克贼。名为负也。}脉滑而数者。有宿食也。当下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":256,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '256、阳明少阳合病。必下利。$a{其脉不负者。为顺也。负者。失也。互相克贼。名为负也。}脉滑而数者。有宿食也。当下之。宜$f{大承气汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3989D9WiMC4', 4, '{"title":"第257条・辨阳明病脉证并治第八","description":"<p>257、病人无表里证。发热七八日。虽脉浮数者。可下之。假令已下。脉数不解。合热则消谷喜饥。至六七日不大便者。有瘀血。宜$f{抵当汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":257,"note":"","videoMemo":"","fangList":["抵当汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '257、病人无表里证。发热七八日。虽脉浮数者。可下之。假令已下。脉数不解。合热则消谷喜饥。至六七日不大便者。有瘀血。宜$f{抵当汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HkSy19B9W9p', 4, '{"title":"第258条・辨阳明病脉证并治第八","description":"<p>258、若脉数不解。而下不止。必协热便脓血也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":258,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '258、若脉数不解。而下不止。必协热便脓血也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZoxO7WYuNfb', 4, '{"title":"第259条・辨阳明病脉证并治第八","description":"<p>259、伤寒发汗已。身目为黄。所以然者。以寒湿在里不解故也。以为不可下也。$a{于寒湿中求之。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":259,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '259、伤寒发汗已。身目为黄。所以然者。以寒湿在里不解故也。以为不可下也。$a{于寒湿中求之。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZXG24hnEluq', 4, '{"title":"第260条・辨阳明病脉证并治第八","description":"<p>260、伤寒七八日。身黄如橘子色。小便不利。腹微满者。$f{茵陈蒿汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":260,"note":"","videoMemo":"","fangList":["茵陈蒿汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '260、伤寒七八日。身黄如橘子色。小便不利。腹微满者。$f{茵陈蒿汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jo62Lq45WLy', 4, '{"title":"第261条・辨阳明病脉证并治第八","description":"<p>261、伤寒身黄。发热。$f{栀子檗皮汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":261,"note":"","videoMemo":"","fangList":["栀子檗皮汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '261、伤寒身黄。发热。$f{栀子檗皮汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oi2AClK6H1i', 4, '{"title":"第262条・辨阳明病脉证并治第八","description":"<p>262、伤寒瘀热在里。身必黄。$f{麻黄连轺赤小豆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":262,"note":"","videoMemo":"","fangList":["麻黄连轺赤小豆汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '262、伤寒瘀热在里。身必黄。$f{麻黄连轺赤小豆汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zbmEiZv2ATl');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i8n55YNtlTd', 4, '{"title":"第263条・辨少阳病脉证并治第九","description":"<p>263、少阳之为病。口苦。咽干。目眩也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":263,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '263、少阳之为病。口苦。咽干。目眩也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dmQ4LhriJBa', 4, '{"title":"第264条・辨少阳病脉证并治第九","description":"<p>264、少阳中风。两耳无所闻。目赤。胸中满而烦者。不可吐下。吐下则悸而惊。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":264,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '264、少阳中风。两耳无所闻。目赤。胸中满而烦者。不可吐下。吐下则悸而惊。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hHyZihp1Nk4', 4, '{"title":"第265条・辨少阳病脉证并治第九","description":"<p>265、伤寒。脉弦细。头痛发热者。属少阳。少阳不可发汗。发汗则谵语。$a{此属胃。}胃和则愈。$a{胃不和。烦而悸。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":265,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '265、伤寒。脉弦细。头痛发热者。属少阳。少阳不可发汗。发汗则谵语。$a{此属胃。}胃和则愈。$a{胃不和。烦而悸。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('69jN07HyPQG', 4, '{"title":"第266条・辨少阳病脉证并治第九","description":"<p>266、本太阳病不解。转入少阳者。胁下硬满。干呕不能食。往来寒热。尚未吐下。脉沉紧者。与$f{小柴胡汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":266,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '266、本太阳病不解。转入少阳者。胁下硬满。干呕不能食。往来寒热。尚未吐下。脉沉紧者。与$f{小柴胡汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('v0Zx3oNlJc8', 4, '{"title":"第267条・辨少阳病脉证并治第九","description":"<p>267、若已吐、下、发汗、温针。谵语。$f{柴胡汤}证罢。此为坏病。$a{知犯何逆。以法治之。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":267,"note":"","videoMemo":"","fangList":["柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '267、若已吐、下、发汗、温针。谵语。$f{柴胡汤}证罢。此为坏病。$a{知犯何逆。以法治之。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ur0q1Yv6OvF', 4, '{"title":"第268条・辨少阳病脉证并治第九","description":"<p>268、三阳合病。脉浮大。$a{上关上。}但欲眠睡。目合则汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":268,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '268、三阳合病。脉浮大。$a{上关上。}但欲眠睡。目合则汗。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p3eLObdHtHg', 4, '{"title":"第269条・辨少阳病脉证并治第九","description":"<p>269、伤寒六七日。无大热。其人躁烦者。此为阳去入阴故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":269,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '269、伤寒六七日。无大热。其人躁烦者。此为阳去入阴故也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gHW10ymWoez', 4, '{"title":"第270条・辨少阳病脉证并治第九","description":"<p>270、伤寒三日。三阳为尽。三阴当受邪。其人反能食而不呕。此为三阴不受邪也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":270,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '270、伤寒三日。三阳为尽。三阴当受邪。其人反能食而不呕。此为三阴不受邪也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yCgpcODfyVx', 4, '{"title":"第271条・辨少阳病脉证并治第九","description":"<p>271、伤寒三日。少阳脉小者。欲已也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":271,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '271、伤寒三日。少阳脉小者。欲已也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('shnvQo5T16G', 4, '{"title":"第272条・辨少阳病脉证并治第九","description":"<p>272、少阳病。欲解时。从寅至辰上。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":272,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '272、少阳病。欲解时。从寅至辰上。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'xPqRL6Y0sER');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BIpzrcNKxfS', 4, '{"title":"第273条・辨太阴病脉证并治第十","description":"<p>273、太阴之为病。腹满而吐。食不下。自利益甚。时腹自痛。若下之。必胸下结硬。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":273,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '273、太阴之为病。腹满而吐。食不下。自利益甚。时腹自痛。若下之。必胸下结硬。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e0Vb1PMRQIm', 4, '{"title":"第274条・辨太阴病脉证并治第十","description":"<p>274、太阴中风。四肢烦疼。阳微阴涩而长者。为欲愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":274,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '274、太阴中风。四肢烦疼。阳微阴涩而长者。为欲愈。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UPHemKKw9gm', 4, '{"title":"第275条・辨太阴病脉证并治第十","description":"<p>275、太阴病。欲解时。从亥至丑上。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":275,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '275、太阴病。欲解时。从亥至丑上。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BCosd5r3s3C', 4, '{"title":"第276条・辨太阴病脉证并治第十","description":"<p>276、太阴病。脉浮者。可发汗。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":276,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '276、太阴病。脉浮者。可发汗。宜$f{桂枝汤}。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z0D4XCKWQc3', 4, '{"title":"第277条・辨太阴病脉证并治第十","description":"<p>277、自利不渴者。属太阴。以其藏有寒故也。当温之。$a{宜服四逆辈。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":277,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '277、自利不渴者。属太阴。以其藏有寒故也。当温之。$a{宜服四逆辈。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RdjM7pgEmer', 4, '{"title":"第278条・辨太阴病脉证并治第十","description":"<p>278、伤寒脉浮而缓。手足自温者。系在太阴。太阴当发身黄。若小便自利者。不能发黄。至七八日。虽暴烦下利日十余行。必自止。$a{以脾家实。腐秽当去故也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":278,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '278、伤寒脉浮而缓。手足自温者。系在太阴。太阴当发身黄。若小便自利者。不能发黄。至七八日。虽暴烦下利日十余行。必自止。$a{以脾家实。腐秽当去故也。}', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vwluyv9RUEx', 4, '{"title":"第279条・辨太阴病脉证并治第十","description":"<p>279、本太阳病。医反下之。因尔腹满时痛者。$a{属太阴也。}$f{桂枝加芍药汤}主之。大实痛者。$f{桂枝加大黄汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":279,"note":"","videoMemo":"","fangList":["桂枝加芍药汤","桂枝加大黄汤"],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '279、本太阳病。医反下之。因尔腹满时痛者。$a{属太阴也。}$f{桂枝加芍药汤}主之。大实痛者。$f{桂枝加大黄汤}主之。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uIJGmg0ioBs', 4, '{"title":"第280条・辨太阴病脉证并治第十","description":"<p>280、太阴为病。脉弱。其人续自便利。设当行$u{大黄}、$u{芍药}者。宜减之。以其人胃气弱。易动故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":280,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '2024-09-17T00:57:26.000Z', '280、太阴为病。脉弱。其人续自便利。设当行$u{大黄}、$u{芍药}者。宜减之。以其人胃气弱。易动故也。', '2024-09-17T00:57:26.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'jhjChJM4pf5');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a5YhcK3FVRR', 4, '{"title":"第281条・辨少阴病脉证并治第十一","description":"<p>281、少阴之为病。脉微细。但欲寐也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":281,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '281、少阴之为病。脉微细。但欲寐也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c60dTRRWIiz', 4, '{"title":"第282条・辨少阴病脉证并治第十一","description":"<p>282、少阴病。欲吐不吐。心烦。但欲寐。五六日自利而渴者。$a{属少阴也。}虚故引水自救。若小便色白者。少阴病形悉具。$a{小便白者。以下焦虚有寒。不能制水。故令色白也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":282,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '282、少阴病。欲吐不吐。心烦。但欲寐。五六日自利而渴者。$a{属少阴也。}虚故引水自救。若小便色白者。少阴病形悉具。$a{小便白者。以下焦虚有寒。不能制水。故令色白也。}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2WAQYITBfHy', 4, '{"title":"第283条・辨少阴病脉证并治第十一","description":"<p>283、病人脉阴阳俱紧。反汗出者。亡阳也。此属少阴。法当咽痛而复吐利。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":283,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '283、病人脉阴阳俱紧。反汗出者。亡阳也。此属少阴。法当咽痛而复吐利。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('As9Ya1pffM2', 4, '{"title":"第284条・辨少阴病脉证并治第十一","description":"<p>284、少阴病。咳而下利。谵语者。被火气劫故也。小便必难。以强责少阴汗也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":284,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '284、少阴病。咳而下利。谵语者。被火气劫故也。小便必难。以强责少阴汗也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7dMrFTMH1GS', 4, '{"title":"第285条・辨少阴病脉证并治第十一","description":"<p>285、少阴病。脉细沉数。病为在里。不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":285,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '285、少阴病。脉细沉数。病为在里。不可发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Y6W0bW1z53', 4, '{"title":"第286条・辨少阴病脉证并治第十一","description":"<p>286、少阴病。脉微。不可发汗。亡阳故也。阳已虚。尺脉弱涩者。复不可下之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":286,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '286、少阴病。脉微。不可发汗。亡阳故也。阳已虚。尺脉弱涩者。复不可下之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wibma2C8a4P', 4, '{"title":"第287条・辨少阴病脉证并治第十一","description":"<p>287、少阴病。脉紧。至七八日。自下利。脉暴微。手足反温。脉紧反去者。为欲解也。虽烦。下利必自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":287,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '287、少阴病。脉紧。至七八日。自下利。脉暴微。手足反温。脉紧反去者。为欲解也。虽烦。下利必自愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4esHru3GNND', 4, '{"title":"第288条・辨少阴病脉证并治第十一","description":"<p>288、少阴病。下利。若利自止。恶寒而踡卧。手足温者。可治。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":288,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '288、少阴病。下利。若利自止。恶寒而踡卧。手足温者。可治。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
