INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UFUbOef7u89', 4, '{"title":"第315条・辨少阴病脉证并治第十一","description":"<p>315、少阴病。下利。脉微者。与$f{白通汤}。利不止。厥逆无脉。干呕烦者。$f{白通加猪胆汁汤}主之。$a{服汤。脉暴出者死。微续者生。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":315,"note":"","videoMemo":"","fangList":["白通汤","白通加猪胆汁汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '315、少阴病。下利。脉微者。与$f{白通汤}。利不止。厥逆无脉。干呕烦者。$f{白通加猪胆汁汤}主之。$a{服汤。脉暴出者死。微续者生。}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M4zrNFdD6uw', 4, '{"title":"第316条・辨少阴病脉证并治第十一","description":"<p>316、少阴病。二三日不已。至四五日。腹痛。小便不利。四肢沉重疼痛。$a{自下利者。此为有水气。}其人或咳。或小便利。或下利。或呕者。$f{真武汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":316,"note":"","videoMemo":"","fangList":["真武汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '316、少阴病。二三日不已。至四五日。腹痛。小便不利。四肢沉重疼痛。$a{自下利者。此为有水气。}其人或咳。或小便利。或下利。或呕者。$f{真武汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aGMj0V6pxDz', 4, '{"title":"第317条・辨少阴病脉证并治第十一","description":"<p>317、少阴病。下利清谷。里寒外热。手足厥逆。脉微欲绝。身反不恶寒。其人面色赤。或腹痛。或干呕。或咽痛。或利止脉不出者。$f{通脉四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":317,"note":"","videoMemo":"","fangList":["通脉四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '317、少阴病。下利清谷。里寒外热。手足厥逆。脉微欲绝。身反不恶寒。其人面色赤。或腹痛。或干呕。或咽痛。或利止脉不出者。$f{通脉四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MFlmrE234Jl', 4, '{"title":"第318条・辨少阴病脉证并治第十一","description":"<p>318、少阴病。$a{四逆。}其人或咳。或悸。或小便不利。或腹中痛。或泄利下重者。$f{四逆散}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":318,"note":"","videoMemo":"","fangList":["四逆散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '318、少阴病。$a{四逆。}其人或咳。或悸。或小便不利。或腹中痛。或泄利下重者。$f{四逆散}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W2KTHQjkpBm', 4, '{"title":"第319条・辨少阴病脉证并治第十一","description":"<p>319、少阴病。下利六七日。咳而呕渴。心烦不得眠者。$f{猪苓汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":319,"note":"","videoMemo":"","fangList":["猪苓汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '319、少阴病。下利六七日。咳而呕渴。心烦不得眠者。$f{猪苓汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gwStcoeBrWI', 4, '{"title":"第320条・辨少阴病脉证并治第十一","description":"<p>320、少阴病。得之二三日。口燥咽干者。急下之。宜$f{大承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":320,"note":"","videoMemo":"","fangList":["大承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '320、少阴病。得之二三日。口燥咽干者。急下之。宜$f{大承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
