INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('btFEAQQSI3X', 4, '{"title":"第324条・辨少阴病脉证并治第十一","description":"<p>324、少阴病。饮食入口则吐。心中温温欲吐。复不能吐。始得之。手足寒。$a{脉弦迟者。此胸中实。}不可下也。$a{当吐之。}若膈上有寒饮。干呕者。不可吐也。当温之。宜$f{四逆汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":324,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '324、少阴病。饮食入口则吐。心中温温欲吐。复不能吐。始得之。手足寒。$a{脉弦迟者。此胸中实。}不可下也。$a{当吐之。}若膈上有寒饮。干呕者。不可吐也。当温之。宜$f{四逆汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jkfuN6tjr2d', 4, '{"title":"第325条・辨少阴病脉证并治第十一","description":"<p>325、少阴病。下利。脉微涩。呕而汗出。必数更衣。反少者。当温其上。灸之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":325,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '325、少阴病。下利。脉微涩。呕而汗出。必数更衣。反少者。当温其上。灸之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', '96G3ec0yvSM');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h88Do85H21a', 4, '{"title":"第326条・辨厥阴病脉证并治第十二","description":"<p>326、厥阴之为病。$a{消渴。}气上撞心。心中疼热。饥而不欲食。食则吐。$a{吐蚘。}下之。利不止。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":326,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '326、厥阴之为病。$a{消渴。}气上撞心。心中疼热。饥而不欲食。食则吐。$a{吐蚘。}下之。利不止。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ps24Cq7LVTx', 4, '{"title":"第327条・辨厥阴病脉证并治第十二","description":"<p>327、厥阴中风。脉微浮为欲愈。不浮为未愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":327,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '327、厥阴中风。脉微浮为欲愈。不浮为未愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
