INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3h0Gr3WWAJk', 4, '{"title":"第331条・辨厥阴病脉证并治第十二","description":"<p>331、伤寒先厥。后发热而利者。必自止。见厥复利。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":331,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '331、伤寒先厥。后发热而利者。必自止。见厥复利。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EPw98hikok6', 4, '{"title":"第332条・辨厥阴病脉证并治第十二","description":"<p>332、伤寒始发热六日。厥反九日而利。凡厥利者。当不能食。今反能食者。恐为除中。食以索饼。不发热者。知胃气尚在。必愈。恐暴热来出而复去也。后三日脉之。其热续在者。期之旦日夜半愈。所以然者。本发热六日。厥反九日。复发热三日。并前六日。亦为九日。与厥相应。故期之旦日夜半愈。后三日脉之而脉数。其热不罢者。此为热气有余。必发痈脓也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":332,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '332、伤寒始发热六日。厥反九日而利。凡厥利者。当不能食。今反能食者。恐为除中。食以索饼。不发热者。知胃气尚在。必愈。恐暴热来出而复去也。后三日脉之。其热续在者。期之旦日夜半愈。所以然者。本发热六日。厥反九日。复发热三日。并前六日。亦为九日。与厥相应。故期之旦日夜半愈。后三日脉之而脉数。其热不罢者。此为热气有余。必发痈脓也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eoYa8KW3UGy', 4, '{"title":"第333条・辨厥阴病脉证并治第十二","description":"<p>333、伤寒脉迟六七日。而反与$f{黄芩汤}彻其热。脉迟为寒。今与$f{黄芩汤}复除其热。腹中应冷。当不能食。今反能食。此名除中。必死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":333,"note":"","videoMemo":"","fangList":["黄芩汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '333、伤寒脉迟六七日。而反与$f{黄芩汤}彻其热。脉迟为寒。今与$f{黄芩汤}复除其热。腹中应冷。当不能食。今反能食。此名除中。必死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RRbR8Ho14EW', 4, '{"title":"第334条・辨厥阴病脉证并治第十二","description":"<p>334、伤寒先厥后发热。下利必自止。而反汗出。咽中痛者。其喉为痹。发热无汗。而利必自止。若不止。必便脓血。便脓血者。其喉不痹。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":334,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '334、伤寒先厥后发热。下利必自止。而反汗出。咽中痛者。其喉为痹。发热无汗。而利必自止。若不止。必便脓血。便脓血者。其喉不痹。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1gbJQDpHbVD', 4, '{"title":"第335条・辨厥阴病脉证并治第十二","description":"<p>335、伤寒一二日至四五日。厥者必发热。前热者后必厥。厥深者热亦深。厥微者热亦微。厥应下之。而反发汗者。必口伤烂赤。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":335,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '335、伤寒一二日至四五日。厥者必发热。前热者后必厥。厥深者热亦深。厥微者热亦微。厥应下之。而反发汗者。必口伤烂赤。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y90ZxsOSkwh', 4, '{"title":"第336条・辨厥阴病脉证并治第十二","description":"<p>336、伤寒病。厥五日。热亦五日。设六日。当复厥。不厥者自愈。厥终不过五日。以热五日。故知自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":336,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '336、伤寒病。厥五日。热亦五日。设六日。当复厥。不厥者自愈。厥终不过五日。以热五日。故知自愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SE3D49z41Yl', 4, '{"title":"第337条・辨厥阴病脉证并治第十二","description":"<p>337、凡厥者。阴阳气不相顺接。便为厥。$a{厥者。手足逆冷者是也。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":337,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '337、凡厥者。阴阳气不相顺接。便为厥。$a{厥者。手足逆冷者是也。}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('97Grqd3TmJI', 4, '{"title":"第338条・辨厥阴病脉证并治第十二","description":"<p>338、伤寒。脉微而厥。至七八日肤冷。其人躁无暂安时者。$a{此为藏厥。}非蚘厥也。$a{蚘厥者。其人当吐蚘。}令病者静。而复时烦$a{者}。$a{此为藏寒。蚘上入其膈。故烦。}须臾复止。得食而呕。又烦。$a{烦者。蚘闻食臭出。}其人常自吐蚘。蚘厥者。$f{乌梅丸}主之。$a{又主久利。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":338,"note":"","videoMemo":"","fangList":["乌梅丸"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '338、伤寒。脉微而厥。至七八日肤冷。其人躁无暂安时者。$a{此为藏厥。}非蚘厥也。$a{蚘厥者。其人当吐蚘。}令病者静。而复时烦$a{者}。$a{此为藏寒。蚘上入其膈。故烦。}须臾复止。得食而呕。又烦。$a{烦者。蚘闻食臭出。}其人常自吐蚘。蚘厥者。$f{乌梅丸}主之。$a{又主久利。}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('e8jtuVfcMPu', 4, '{"title":"第339条・辨厥阴病脉证并治第十二","description":"<p>339、伤寒热少微厥。指头寒。嘿嘿不欲食。烦躁。数日。小便利。色白者。此热除也。欲得食。其病为愈。若厥而呕。胸胁烦满者。其后必便血。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":339,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '339、伤寒热少微厥。指头寒。嘿嘿不欲食。烦躁。数日。小便利。色白者。此热除也。欲得食。其病为愈。若厥而呕。胸胁烦满者。其后必便血。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sdooMTDc0DR', 4, '{"title":"第340条・辨厥阴病脉证并治第十二","description":"<p>340、病者手足厥冷。言我不结胸。小腹满。按之痛者。此冷结在膀胱关元也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":340,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '340、病者手足厥冷。言我不结胸。小腹满。按之痛者。此冷结在膀胱关元也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qaChDh8xHL3', 4, '{"title":"第341条・辨厥阴病脉证并治第十二","description":"<p>341、伤寒发热四日。厥反三日。复热四日。厥少热多者。其病当愈。四日至七日。热不除者。必便脓血。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":341,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '341、伤寒发热四日。厥反三日。复热四日。厥少热多者。其病当愈。四日至七日。热不除者。必便脓血。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O6RfyH1F3vq', 4, '{"title":"第342条・辨厥阴病脉证并治第十二","description":"<p>342、伤寒厥四日。热反三日。复厥五日。其病为进。寒多热少。阳气退。故为进也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":342,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '342、伤寒厥四日。热反三日。复厥五日。其病为进。寒多热少。阳气退。故为进也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('g3i7equQwX0', 4, '{"title":"第343条・辨厥阴病脉证并治第十二","description":"<p>343、伤寒六七日。脉微。手足厥冷。烦躁。灸厥阴。厥不还者。死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":343,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '343、伤寒六七日。脉微。手足厥冷。烦躁。灸厥阴。厥不还者。死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9NuqcW4up2g', 4, '{"title":"第344条・辨厥阴病脉证并治第十二","description":"<p>344、伤寒发热。下利厥逆。躁不得卧者。死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":344,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '344、伤寒发热。下利厥逆。躁不得卧者。死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CpSkMau3kTV', 4, '{"title":"第345条・辨厥阴病脉证并治第十二","description":"<p>345、伤寒发热。下利至甚。厥不止者。死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":345,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '345、伤寒发热。下利至甚。厥不止者。死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PeUd5K7C05b', 4, '{"title":"第346条・辨厥阴病脉证并治第十二","description":"<p>346、伤寒六七日不利。便发热而利。其人汗出不止者。死。有阴无阳故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":346,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '346、伤寒六七日不利。便发热而利。其人汗出不止者。死。有阴无阳故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iqYbk80OmFX', 4, '{"title":"第347条・辨厥阴病脉证并治第十二","description":"<p>347、伤寒五六日。不结胸。腹濡。脉虚复厥者。不可下。此亡血。下之。死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":347,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '347、伤寒五六日。不结胸。腹濡。脉虚复厥者。不可下。此亡血。下之。死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PFND34SrVDC', 4, '{"title":"第348条・辨厥阴病脉证并治第十二","description":"<p>348、发热而厥。七日下利者。为难治。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":348,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '348、发热而厥。七日下利者。为难治。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
