INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MRhz0fGNK4Z', 4, '{"title":"第350条・辨厥阴病脉证并治第十二","description":"<p>350、伤寒。脉滑而厥者。里有热。$f{白虎汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":350,"note":"","videoMemo":"","fangList":["白虎汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '350、伤寒。脉滑而厥者。里有热。$f{白虎汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bXvzpuwldT8', 4, '{"title":"第351条・辨厥阴病脉证并治第十二","description":"<p>351、手足厥寒。脉细欲绝者。$f{当归四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":351,"note":"","videoMemo":"","fangList":["当归四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '351、手足厥寒。脉细欲绝者。$f{当归四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VRJyP1NYxOb', 4, '{"title":"第352条・辨厥阴病脉证并治第十二","description":"<p>352、若其人内有久寒者。宜$f{当归四逆加吴茱萸生姜汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":352,"note":"","videoMemo":"","fangList":["当归四逆加吴茱萸生姜汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '352、若其人内有久寒者。宜$f{当归四逆加吴茱萸生姜汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oo7fmh6Hpud', 4, '{"title":"第353条・辨厥阴病脉证并治第十二","description":"<p>353、大汗出。热不去。内拘急。四肢疼。又下利厥逆而恶寒者。$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":353,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '353、大汗出。热不去。内拘急。四肢疼。又下利厥逆而恶寒者。$f{四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a2ByrcZcpGi', 4, '{"title":"第354条・辨厥阴病脉证并治第十二","description":"<p>354、大汗。若大下利而厥冷者。$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":354,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '354、大汗。若大下利而厥冷者。$f{四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TaLluXYJwVY', 4, '{"title":"第355条・辨厥阴病脉证并治第十二","description":"<p>355、病人手足厥冷。脉乍紧者。邪结在胸中。心下满而烦。饥不能食者。病在胸中。当须吐之。宜$f{瓜蒂散}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":355,"note":"","videoMemo":"","fangList":["瓜蒂散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '355、病人手足厥冷。脉乍紧者。邪结在胸中。心下满而烦。饥不能食者。病在胸中。当须吐之。宜$f{瓜蒂散}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7LFY6EtKXYH', 4, '{"title":"第356条・辨厥阴病脉证并治第十二","description":"<p>356、伤寒厥而心下悸。宜先治水。当服$f{茯苓甘草汤}。却治其厥。不尔。水渍入胃。必作利也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":356,"note":"","videoMemo":"","fangList":["茯苓甘草汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '356、伤寒厥而心下悸。宜先治水。当服$f{茯苓甘草汤}。却治其厥。不尔。水渍入胃。必作利也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iyF1z05No4G', 4, '{"title":"第357条・辨厥阴病脉证并治第十二","description":"<p>357、伤寒六七日。大下后。$a{寸}脉沉而迟。手足厥逆。下部脉不至。喉咽不利。唾脓血。泄利不止者。$a{为难治。}$f{麻黄升麻汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":357,"note":"","videoMemo":"","fangList":["麻黄升麻汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '357、伤寒六七日。大下后。$a{寸}脉沉而迟。手足厥逆。下部脉不至。喉咽不利。唾脓血。泄利不止者。$a{为难治。}$f{麻黄升麻汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wCjECOjejRu', 4, '{"title":"第358条・辨厥阴病脉证并治第十二","description":"<p>358、伤寒四五日。腹中痛。若转气下趋少腹者。此欲自利也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":358,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '358、伤寒四五日。腹中痛。若转气下趋少腹者。此欲自利也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JSpbK2kzNv7', 4, '{"title":"第359条・辨厥阴病脉证并治第十二","description":"<p>359、伤寒。本自寒下。医反复吐下之。寒格。更逆吐下。若食入口即吐。$f{干姜黄芩黄连人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":359,"note":"","videoMemo":"","fangList":["干姜黄芩黄连人参汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '359、伤寒。本自寒下。医反复吐下之。寒格。更逆吐下。若食入口即吐。$f{干姜黄芩黄连人参汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TxgUs7h1hC6', 4, '{"title":"第360条・辨厥阴病脉证并治第十二","description":"<p>360、下利。有微热而渴。脉弱者。今自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":360,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '360、下利。有微热而渴。脉弱者。今自愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uQUvLv3jbT1', 4, '{"title":"第361条・辨厥阴病脉证并治第十二","description":"<p>361、下利。脉数。有微热汗出。今自愈。设复紧。为未解。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":361,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '361、下利。脉数。有微热汗出。今自愈。设复紧。为未解。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PZc37f8e3dX', 4, '{"title":"第362条・辨厥阴病脉证并治第十二","description":"<p>362、下利。手足厥冷。无脉者。灸之。不温。若脉不还。反微喘者。死。少阴负跌阳者为顺也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":362,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '362、下利。手足厥冷。无脉者。灸之。不温。若脉不还。反微喘者。死。少阴负跌阳者为顺也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('61ZqybuC0OY', 4, '{"title":"第363条・辨厥阴病脉证并治第十二","description":"<p>363、下利。寸脉反浮数。尺中自涩者。必清脓血。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":363,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '363、下利。寸脉反浮数。尺中自涩者。必清脓血。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q5eW7jkeSeT', 4, '{"title":"第364条・辨厥阴病脉证并治第十二","description":"<p>364、下利清谷。不可攻表。汗出必胀满。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":364,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '364、下利清谷。不可攻表。汗出必胀满。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I294Rc9XUEP', 4, '{"title":"第365条・辨厥阴病脉证并治第十二","description":"<p>365、下利。脉沉弦者。下重也。脉大者。为未止。脉微弱数者。为欲自止。虽发热。不死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":365,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '365、下利。脉沉弦者。下重也。脉大者。为未止。脉微弱数者。为欲自止。虽发热。不死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fAjXCU0x9g5', 4, '{"title":"第366条・辨厥阴病脉证并治第十二","description":"<p>366、下利。脉沉而迟。其人面少赤。身有微热。下利清谷者。必郁冒汗出而解。病人必微厥。所以然者。其面戴阳。下虚故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":366,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '366、下利。脉沉而迟。其人面少赤。身有微热。下利清谷者。必郁冒汗出而解。病人必微厥。所以然者。其面戴阳。下虚故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5YzR2mVyfLg', 4, '{"title":"第367条・辨厥阴病脉证并治第十二","description":"<p>367、下利。脉数而渴者。今自愈。设不差。必清脓血。以有热故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":367,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '367、下利。脉数而渴者。今自愈。设不差。必清脓血。以有热故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6BUHX8UViA6', 4, '{"title":"第368条・辨厥阴病脉证并治第十二","description":"<p>368、下利后脉绝。手足厥冷。晬时脉还。手足温者生。脉不还者死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":368,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '368、下利后脉绝。手足厥冷。晬时脉还。手足温者生。脉不还者死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DMAj4JTnSV3', 4, '{"title":"第369条・辨厥阴病脉证并治第十二","description":"<p>369、伤寒下利。日十余行。脉反实者。死。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":369,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '369、伤寒下利。日十余行。脉反实者。死。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6vGlCN9zm1Z', 4, '{"title":"第370条・辨厥阴病脉证并治第十二","description":"<p>370、下利清谷。里寒外热。汗出而厥者。$f{通脉四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":370,"note":"","videoMemo":"","fangList":["通脉四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '370、下利清谷。里寒外热。汗出而厥者。$f{通脉四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p2pkGUUI8k8', 4, '{"title":"第371条・辨厥阴病脉证并治第十二","description":"<p>371、热利。下重者。$f{白头翁汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":371,"note":"","videoMemo":"","fangList":["白头翁汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '371、热利。下重者。$f{白头翁汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aZxq4pRxhY7', 4, '{"title":"第372条・辨厥阴病脉证并治第十二","description":"<p>372、下利腹胀满。身体疼痛者。先温其里。乃攻其表。温里。宜$f{四逆汤}。攻表。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":372,"note":"","videoMemo":"","fangList":["四逆汤","桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '372、下利腹胀满。身体疼痛者。先温其里。乃攻其表。温里。宜$f{四逆汤}。攻表。宜$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2XwwmZw9yDj', 4, '{"title":"第373条・辨厥阴病脉证并治第十二","description":"<p>373、下利。欲饮水者。以有热故也。$f{白头翁汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":373,"note":"","videoMemo":"","fangList":["白头翁汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '373、下利。欲饮水者。以有热故也。$f{白头翁汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('d0qbzZKPta8', 4, '{"title":"第374条・辨厥阴病脉证并治第十二","description":"<p>374、下利。谵语者。有燥屎也。宜$f{小承气汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":374,"note":"","videoMemo":"","fangList":["小承气汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '374、下利。谵语者。有燥屎也。宜$f{小承气汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cOyJr0bRfxl', 4, '{"title":"第375条・辨厥阴病脉证并治第十二","description":"<p>375、下利后。更烦。按之心下濡者。为虚烦也。宜$f{栀子豉汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":375,"note":"","videoMemo":"","fangList":["栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '375、下利后。更烦。按之心下濡者。为虚烦也。宜$f{栀子豉汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2m2nFkJnOVi', 4, '{"title":"第376条・辨厥阴病脉证并治第十二","description":"<p>376、呕家。有痈脓者。不可治呕。脓尽自愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":376,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '376、呕家。有痈脓者。不可治呕。脓尽自愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YfYSfA7ydp6', 4, '{"title":"第377条・辨厥阴病脉证并治第十二","description":"<p>377、呕而脉弱。小便复利。身有微热。见厥者难治。$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":377,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '377、呕而脉弱。小便复利。身有微热。见厥者难治。$f{四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('W6w1krKWe3C', 4, '{"title":"第378条・辨厥阴病脉证并治第十二","description":"<p>378、干呕。吐涎沫。头痛者。$f{吴茱萸汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":378,"note":"","videoMemo":"","fangList":["吴茱萸汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '378、干呕。吐涎沫。头痛者。$f{吴茱萸汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OOKqotfP7UF', 4, '{"title":"第379条・辨厥阴病脉证并治第十二","description":"<p>379、呕而发热者。$f{小柴胡汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":379,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '379、呕而发热者。$f{小柴胡汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xq4lCdAitzS', 4, '{"title":"第380条・辨厥阴病脉证并治第十二","description":"<p>380、伤寒大吐大下之。极虚。复极汗者。其人外气怫郁。复与之水。以发其汗。因得哕。所以然者。胃中寒冷故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":380,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '380、伤寒大吐大下之。极虚。复极汗者。其人外气怫郁。复与之水。以发其汗。因得哕。所以然者。胃中寒冷故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('brITQYaLjth', 4, '{"title":"第381条・辨厥阴病脉证并治第十二","description":"<p>381、伤寒。哕而腹满。视其前后。知何部不利。利之则愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":381,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '381、伤寒。哕而腹满。视其前后。知何部不利。利之则愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'G0Eqx1ccWzG');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eYQch7ae1c9', 4, '{"title":"第382条・辨霍乱病脉证并治第十三","description":"<p>382、问曰。病有霍乱者何？答曰：呕吐而利。此名霍乱。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":382,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '382、问曰。病有霍乱者何？答曰：呕吐而利。此名霍乱。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a315k22or5X', 4, '{"title":"第383条・辨霍乱病脉证并治第十三","description":"<p>383、问曰：病发热。头痛。身疼。恶寒。吐利者。此属何病？答曰。此名霍乱。霍乱自吐下。又利止。复更发热也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":383,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '383、问曰：病发热。头痛。身疼。恶寒。吐利者。此属何病？答曰。此名霍乱。霍乱自吐下。又利止。复更发热也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GXXnnDDge7o', 4, '{"title":"第384条・辨霍乱病脉证并治第十三","description":"<p>384、伤寒。其脉微涩者。本是霍乱。今是伤寒。却四五日。至阴经上。转入阴必利。本呕下利者。不可治也。欲似大便。而反失气。仍不利者。此属阳明也。便必硬。十三日愈。所以然者。经尽故也。下利后。当便硬。硬则能食者愈。今反不能食。到后经中。颇能食。复过一经能食。过之一日当愈。不愈者。不属阳明也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":384,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '384、伤寒。其脉微涩者。本是霍乱。今是伤寒。却四五日。至阴经上。转入阴必利。本呕下利者。不可治也。欲似大便。而反失气。仍不利者。此属阳明也。便必硬。十三日愈。所以然者。经尽故也。下利后。当便硬。硬则能食者愈。今反不能食。到后经中。颇能食。复过一经能食。过之一日当愈。不愈者。不属阳明也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4fX3cz55Jwf', 4, '{"title":"第385条・辨霍乱病脉证并治第十三","description":"<p>385、$a{(康平本有“吐利”)}恶寒。脉微而复利。$a{利止。亡血也。}$f{四逆加人参汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":385,"note":"","videoMemo":"","fangList":["四逆加人参汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '385、$a{(康平本有“吐利”)}恶寒。脉微而复利。$a{利止。亡血也。}$f{四逆加人参汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MmSlfjWiouX', 4, '{"title":"第386条・辨霍乱病脉证并治第十三","description":"<p>386、霍乱。头痛发热。身疼痛。热多欲饮水者。$f{五苓散}主之。寒多不用水者。$f{理中丸}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":386,"note":"","videoMemo":"","fangList":["五苓散","理中丸"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '386、霍乱。头痛发热。身疼痛。热多欲饮水者。$f{五苓散}主之。寒多不用水者。$f{理中丸}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iNLli4JZSlA', 4, '{"title":"第387条・辨霍乱病脉证并治第十三","description":"<p>387、吐利止而身痛不休者。当消息和解其外。宜$f{桂枝汤}。$a{小和之。}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":387,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '387、吐利止而身痛不休者。当消息和解其外。宜$f{桂枝汤}。$a{小和之。}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PgtqBQzZieE', 4, '{"title":"第388条・辨霍乱病脉证并治第十三","description":"<p>388、吐利汗出。发热恶寒。四肢拘急。手足厥冷者。$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":388,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '388、吐利汗出。发热恶寒。四肢拘急。手足厥冷者。$f{四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lvg5SeIB1tc', 4, '{"title":"第389条・辨霍乱病脉证并治第十三","description":"<p>389、既吐且利。小便复利而大汗出。下利清谷。内寒外热。脉微欲绝者。$f{四逆汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":389,"note":"","videoMemo":"","fangList":["四逆汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '389、既吐且利。小便复利而大汗出。下利清谷。内寒外热。脉微欲绝者。$f{四逆汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aNw6KlLzvWb', 4, '{"title":"第390条・辨霍乱病脉证并治第十三","description":"<p>390、吐已。下断。汗出而厥。四肢拘急不解。脉微欲绝者。$f{通脉四逆加猪胆汁汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":390,"note":"","videoMemo":"","fangList":["通脉四逆加猪胆汁汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '390、吐已。下断。汗出而厥。四肢拘急不解。脉微欲绝者。$f{通脉四逆加猪胆汁汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T12omabE5FX', 4, '{"title":"第391条・辨霍乱病脉证并治第十三","description":"<p>391、吐利发汗。脉平。小烦者。以新虚不胜谷气故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":391,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '391、吐利发汗。脉平。小烦者。以新虚不胜谷气故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'JOypAh9ce6J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Pbl41HVjRYp', 4, '{"title":"第392条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>392、伤寒阴易之为病。其人身体重。少气。少腹里急。或引阴中拘挛。热上冲胸。头重不欲举。眼中生花。膝胫拘急者。$f{烧裈散}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":392,"note":"","videoMemo":"","fangList":["烧裈散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '392、伤寒阴易之为病。其人身体重。少气。少腹里急。或引阴中拘挛。热上冲胸。头重不欲举。眼中生花。膝胫拘急者。$f{烧裈散}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R13YAYUtqm1', 4, '{"title":"第393条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>393、大病差后。劳复者。$f{枳实栀子豉汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":393,"note":"","videoMemo":"","fangList":["枳实栀子豉汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '393、大病差后。劳复者。$f{枳实栀子豉汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KZJOIGbIOp4', 4, '{"title":"第394条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>394、伤寒差以后。更发热。$f{小柴胡汤}主之。脉浮者。以汗解之。脉沉实$a{（一作紧）}者。以下解之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":394,"note":"","videoMemo":"","fangList":["小柴胡汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '394、伤寒差以后。更发热。$f{小柴胡汤}主之。脉浮者。以汗解之。脉沉实$a{（一作紧）}者。以下解之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xV3LeP3yc4U', 4, '{"title":"第395条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>395、大病差后。从腰以下有水气者。$f{牡蛎泽泻散}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":395,"note":"","videoMemo":"","fangList":["牡蛎泽泻散"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '395、大病差后。从腰以下有水气者。$f{牡蛎泽泻散}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('a4YmfLvQgyh', 4, '{"title":"第396条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>396、大病差后。喜唾。久不了了。$a{胸上有寒。当以丸药温之。}宜$f{理中丸}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":396,"note":"","videoMemo":"","fangList":["理中丸"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '396、大病差后。喜唾。久不了了。$a{胸上有寒。当以丸药温之。}宜$f{理中丸}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WgRC31iRtaD', 4, '{"title":"第397条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>397、伤寒解后。虚羸少气。气逆欲吐。$f{竹叶石膏汤}主之。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":397,"note":"","videoMemo":"","fangList":["竹叶石膏汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '397、伤寒解后。虚羸少气。气逆欲吐。$f{竹叶石膏汤}主之。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('414yVDUneYn', 4, '{"title":"第398条・辨阴阳易差后劳复病脉证并治第十四","description":"<p>398、病人脉已解。而日暮微烦。以病新差。人强与谷。脾胃气尚弱。不能消谷。故令微烦。损谷则愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":398,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '398、病人脉已解。而日暮微烦。以病新差。人强与谷。脾胃气尚弱。不能消谷。故令微烦。损谷则愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'zqGXbkI2Oiw');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i5kqMTwk2r7', 4, '{"title":"第1018000条・辨不可发汗病脉证并治第十五","description":"<p>1、夫以为疾病至急。仓卒寻按。要者难得。故重集诸可与不可方治。比之三阴三阳篇中。此易见也。又时有不止是三阳三阴。出在诸可与不可中也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '1、夫以为疾病至急。仓卒寻按。要者难得。故重集诸可与不可方治。比之三阴三阳篇中。此易见也。又时有不止是三阳三阴。出在诸可与不可中也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nl7JEkYZp3A', 4, '{"title":"第1018001条・辨不可发汗病脉证并治第十五","description":"<p>2、少阴病。脉细沉数。病为在里。不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2、少阴病。脉细沉数。病为在里。不可发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3zMubtu9sqJ', 4, '{"title":"第1018002条・辨不可发汗病脉证并治第十五","description":"<p>3、脉浮紧者。法当身疼痛。宜以汗解之。假令尺中迟者。不可发汗。何以知然。以荣气不足。血少故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '3、脉浮紧者。法当身疼痛。宜以汗解之。假令尺中迟者。不可发汗。何以知然。以荣气不足。血少故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dUPrS9Xj88Q', 4, '{"title":"第1018003条・辨不可发汗病脉证并治第十五","description":"<p>4、少阴病。脉微不可发汗。亡阳故也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '4、少阴病。脉微不可发汗。亡阳故也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kr0MzVVsqjS', 4, '{"title":"第1018004条・辨不可发汗病脉证并治第十五","description":"<p>5、脉濡而弱。弱反在关。濡反在巅。微反在上。涩反在下。微则阳气不足。涩则无血。阳气反微。中风汗出而反躁烦。涩则无血。厥而且寒。阳微发汗。躁不得眠。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018004,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '5、脉濡而弱。弱反在关。濡反在巅。微反在上。涩反在下。微则阳气不足。涩则无血。阳气反微。中风汗出而反躁烦。涩则无血。厥而且寒。阳微发汗。躁不得眠。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('p0ZKsA2h3VZ', 4, '{"title":"第1018005条・辨不可发汗病脉证并治第十五","description":"<p>6、动气在右。不可发汗。发汗则衄而渴。心苦烦。饮即吐水。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018005,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '6、动气在右。不可发汗。发汗则衄而渴。心苦烦。饮即吐水。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qmLD36RqdC6', 4, '{"title":"第1018006条・辨不可发汗病脉证并治第十五","description":"<p>7、动气在左。不可发汗。发汗则头眩。汗不止。筋愓肉瞤。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018006,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '7、动气在左。不可发汗。发汗则头眩。汗不止。筋愓肉瞤。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('16OcTdQDkGw', 4, '{"title":"第1018007条・辨不可发汗病脉证并治第十五","description":"<p>8、动气在上。不可发汗。发汗则气上冲。正在心端。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '8、动气在上。不可发汗。发汗则气上冲。正在心端。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rLCZf7vYhgq', 4, '{"title":"第1018008条・辨不可发汗病脉证并治第十五","description":"<p>9、动气在下。不可发汗。发汗则无汗。心中大烦。骨节苦疼。目运。恶寒。食则反吐。谷不得前。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '9、动气在下。不可发汗。发汗则无汗。心中大烦。骨节苦疼。目运。恶寒。食则反吐。谷不得前。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HyFiSgdQbnO', 4, '{"title":"第1018009条・辨不可发汗病脉证并治第十五","description":"<p>10、咽中闭塞。不可发汗。发汗则吐血。气微绝。手足厥冷。欲得踡卧。不能自温。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018009,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '10、咽中闭塞。不可发汗。发汗则吐血。气微绝。手足厥冷。欲得踡卧。不能自温。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('m2i7F6KYayB', 4, '{"title":"第1018010条・辨不可发汗病脉证并治第十五","description":"<p>11、诸脉得数动微弱者。不可发汗。发汗则大便难。腹中干。$a{（一云。小便难。胞中干。）}胃躁而烦。其形相象。根本异源。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018010,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '11、诸脉得数动微弱者。不可发汗。发汗则大便难。腹中干。$a{（一云。小便难。胞中干。）}胃躁而烦。其形相象。根本异源。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('X13XLblcUS2', 4, '{"title":"第1018011条・辨不可发汗病脉证并治第十五","description":"<p>12、脉濡而弱。弱反在关。濡反在巅。弦反在上。微反在下。弦为阳运。微为阴寒。上实下虚。意欲得温。微弦为虚。不可发汗。发汗则寒慄不能自还。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018011,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '12、脉濡而弱。弱反在关。濡反在巅。弦反在上。微反在下。弦为阳运。微为阴寒。上实下虚。意欲得温。微弦为虚。不可发汗。发汗则寒慄不能自还。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DNKsFwHHFwy', 4, '{"title":"第1018012条・辨不可发汗病脉证并治第十五","description":"<p>13、咳者则剧。数吐涎沫。咽中必干。小便不利。心中饥烦。晬时而发。其形似疟。有寒无热。虚而寒慄。咳而发汗。踡而苦满。腹中复坚。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018012,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '13、咳者则剧。数吐涎沫。咽中必干。小便不利。心中饥烦。晬时而发。其形似疟。有寒无热。虚而寒慄。咳而发汗。踡而苦满。腹中复坚。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BphrHegVALh', 4, '{"title":"第1018013条・辨不可发汗病脉证并治第十五","description":"<p>14、厥脉紧。不可发汗。发汗则声乱。咽嘶舌萎。声不得前。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018013,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '14、厥脉紧。不可发汗。发汗则声乱。咽嘶舌萎。声不得前。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fR6MTPTqkuW', 4, '{"title":"第1018014条・辨不可发汗病脉证并治第十五","description":"<p>15、诸逆发汗。病微者难差。剧者言乱。目眩者。死。$a{（一云讝言目眩睛乱者。死。）}命将难全。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018014,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '15、诸逆发汗。病微者难差。剧者言乱。目眩者。死。$a{（一云讝言目眩睛乱者。死。）}命将难全。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8cfHmnc38od', 4, '{"title":"第1018015条・辨不可发汗病脉证并治第十五","description":"<p>16、太阳病得之八九日。如疟状。发热恶寒。热多寒少。其人不呕清便。续自可。一日二三度发。脉微而恶寒者。此阴阳俱虚。不可更发汗也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018015,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '16、太阳病得之八九日。如疟状。发热恶寒。热多寒少。其人不呕清便。续自可。一日二三度发。脉微而恶寒者。此阴阳俱虚。不可更发汗也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kIqEDsuQbPR', 4, '{"title":"第1018016条・辨不可发汗病脉证并治第十五","description":"<p>17、太阳病。发热恶寒。热多寒少。脉微弱者。无阳也。不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018016,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '17、太阳病。发热恶寒。热多寒少。脉微弱者。无阳也。不可发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('F9TIyIQ5tVo', 4, '{"title":"第1018017条・辨不可发汗病脉证并治第十五","description":"<p>18、咽喉干燥者。不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018017,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '18、咽喉干燥者。不可发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
