INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HSJBhZT7s00', 4, '{"title":"第1018023条・辨不可发汗病脉证并治第十五","description":"<p>24、下利不可发汗。汗出必胀满。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018023,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '24、下利不可发汗。汗出必胀满。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
