INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xk7pCj5y4Mo', 4, '{"title":"第1018025条・辨不可发汗病脉证并治第十五","description":"<p>26、伤寒一二日至四五日厥者。必发热。前厥者。后必热。厥深者热亦深。厥微者热亦微。厥应下之。而反发汗者。必口伤烂赤。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018025,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '26、伤寒一二日至四五日厥者。必发热。前厥者。后必热。厥深者热亦深。厥微者热亦微。厥应下之。而反发汗者。必口伤烂赤。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y04yc7JJrfd', 4, '{"title":"第1018026条・辨不可发汗病脉证并治第十五","description":"<p>27、伤寒脉弦细。头痛发热者。属少阳。少阳不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018026,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '27、伤寒脉弦细。头痛发热者。属少阳。少阳不可发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EmKWoQ0Nldi', 4, '{"title":"第1018027条・辨不可发汗病脉证并治第十五","description":"<p>28、伤寒头痛。翕翕发热。形象中风。常微汗出。自呕者。下之益烦。心懊憹如饥。发汗则致痓。身强。难以伸屈。熏之则发黄。不得小便。久则发咳唾。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018027,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '28、伤寒头痛。翕翕发热。形象中风。常微汗出。自呕者。下之益烦。心懊憹如饥。发汗则致痓。身强。难以伸屈。熏之则发黄。不得小便。久则发咳唾。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('atSHpxU3w0x', 4, '{"title":"第1018028条・辨不可发汗病脉证并治第十五","description":"<p>29、太阳与少阳并病。头项强痛。或眩冒。时如结胸。心下痞鞕者。不可发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018028,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '29、太阳与少阳并病。头项强痛。或眩冒。时如结胸。心下痞鞕者。不可发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B2rgmxyKJyK', 4, '{"title":"第1018029条・辨不可发汗病脉证并治第十五","description":"<p>30、太阳病。发汗。因致痓。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018029,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '30、太阳病。发汗。因致痓。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HJGhsifiAad', 4, '{"title":"第1018030条・辨不可发汗病脉证并治第十五","description":"<p>31、少阴病。咳而不利。讝语者。此被火气劫故也。小便必难。以强责少阴。汗也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '31、少阴病。咳而不利。讝语者。此被火气劫故也。小便必难。以强责少阴。汗也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ysq2ZqOjGBn', 4, '{"title":"第1018031条・辨不可发汗病脉证并治第十五","description":"<p>32、少阴病。但厥无汗。而强发之。必动其血。未知从何道出。或从口鼻。或从目出者。是名下厥上竭。为难治。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1018031,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '32、少阴病。但厥无汗。而强发之。必动其血。未知从何道出。或从口鼻。或从目出者。是名下厥上竭。为难治。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'gU00On4ub9J');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h8IAmZrnlSx', 4, '{"title":"第1019000条・辨可发汗病脉证并治第十六","description":"<p>1、大法。春夏宜发汗。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019000,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '1、大法。春夏宜发汗。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PWZtRBfwYPk', 4, '{"title":"第1019001条・辨可发汗病脉证并治第十六","description":"<p>2、凡发汗。欲令手足俱周。时出似漐漐然。一时间许。益佳。不可令如水流离。若病不解当重发汗。汗多者必亡阳。阳虚。不得重发汗也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019001,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2、凡发汗。欲令手足俱周。时出似漐漐然。一时间许。益佳。不可令如水流离。若病不解当重发汗。汗多者必亡阳。阳虚。不得重发汗也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sbS1aAC4uJ1', 4, '{"title":"第1019002条・辨可发汗病脉证并治第十六","description":"<p>3、凡服汤发汗。中病便止。不必尽剂也。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019002,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '3、凡服汤发汗。中病便止。不必尽剂也。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BPX1ohtNcuj', 4, '{"title":"第1019003条・辨可发汗病脉证并治第十六","description":"<p>4、凡云可发汗。无汤者。丸散亦可用。要以汗出为解。然不如汤随证良验。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019003,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '4、凡云可发汗。无汤者。丸散亦可用。要以汗出为解。然不如汤随证良验。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7q57O4Ihkfr', 4, '{"title":"第1019004条・辨可发汗病脉证并治第十六","description":"<p>5、太阳病。外证未解。脉浮弱者。当以汗解。宜$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019004,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '5、太阳病。外证未解。脉浮弱者。当以汗解。宜$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZitLYP6eZhs', 4, '{"title":"第1019005条・辨可发汗病脉证并治第十六","description":"<p>6、脉浮而数者。可发汗。属$f{桂枝汤}。$a{（一法用$f{麻黄汤}。）}</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019005,"note":"","videoMemo":"","fangList":["桂枝汤","麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '6、脉浮而数者。可发汗。属$f{桂枝汤}。$a{（一法用$f{麻黄汤}。）}', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Cizc05xVuNY', 4, '{"title":"第1019006条・辨可发汗病脉证并治第十六","description":"<p>7、阳明病。脉迟。汗出多。微恶寒者。表未解也。可发汗。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019006,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '7、阳明病。脉迟。汗出多。微恶寒者。表未解也。可发汗。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mofchcz4VDv', 4, '{"title":"第1019007条・辨可发汗病脉证并治第十六","description":"<p>8、夫病脉浮大。问病者言但便鞕耳。设利者。为大逆。鞕为实。汗出而解。何以故。脉浮当以汗解。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019007,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '8、夫病脉浮大。问病者言但便鞕耳。设利者。为大逆。鞕为实。汗出而解。何以故。脉浮当以汗解。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wFvO0vQ07sm', 4, '{"title":"第1019008条・辨可发汗病脉证并治第十六","description":"<p>9、伤寒其脉不弦紧而弱。弱者必渴。被火必讝语。弱者发热脉浮。解之当汗出愈。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019008,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '9、伤寒其脉不弦紧而弱。弱者必渴。被火必讝语。弱者发热脉浮。解之当汗出愈。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RdWrFFoF4m2', 4, '{"title":"第1019009条・辨可发汗病脉证并治第十六","description":"<p>10、病人烦热。汗出即解。又如疟状。日晡所发热者。属阳明也。脉浮虚者。当发汗。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019009,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '10、病人烦热。汗出即解。又如疟状。日晡所发热者。属阳明也。脉浮虚者。当发汗。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yQs57u2Ncep', 4, '{"title":"第1019010条・辨可发汗病脉证并治第十六","description":"<p>11、病常自汗出者。此为荣气和。荣气和者。外不谐。以卫气不共荣气谐和故尔。以荣行脉中。卫行脉外。复发其汗。荣卫和。则愈。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019010,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '11、病常自汗出者。此为荣气和。荣气和者。外不谐。以卫气不共荣气谐和故尔。以荣行脉中。卫行脉外。复发其汗。荣卫和。则愈。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qm0iM04ChNz', 4, '{"title":"第1019011条・辨可发汗病脉证并治第十六","description":"<p>12、病人藏无他病。时发热自汗出而不愈者。此卫气不和也。先其时发汗则愈。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019011,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '12、病人藏无他病。时发热自汗出而不愈者。此卫气不和也。先其时发汗则愈。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FkKYczZu8Pk', 4, '{"title":"第1019012条・辨可发汗病脉证并治第十六","description":"<p>13、脉浮而紧。浮则为风。紧则为寒。风则伤卫。寒则伤荣。荣卫俱病。骨节烦疼。可发其汗。宜$f{麻黄汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019012,"note":"","videoMemo":"","fangList":["麻黄汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '13、脉浮而紧。浮则为风。紧则为寒。风则伤卫。寒则伤荣。荣卫俱病。骨节烦疼。可发其汗。宜$f{麻黄汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pDh5GDPRDlO', 4, '{"title":"第1019013条・辨可发汗病脉证并治第十六","description":"<p>14、太阳病不解。热结膀胱。其人如狂。血自下。下者愈。其外未解者。尚未可攻。当先解其外。属$f{桂枝汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019013,"note":"","videoMemo":"","fangList":["桂枝汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '14、太阳病不解。热结膀胱。其人如狂。血自下。下者愈。其外未解者。尚未可攻。当先解其外。属$f{桂枝汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lbXgSlD4Rz5', 4, '{"title":"第1019014条・辨可发汗病脉证并治第十六","description":"<p>15、太阳病。下之微喘者。表未解也。宜$f{桂枝加厚朴杏子汤}。</p>","content_format":"html","_microfeed":{"bookId":"q6u5siNb2hT","receiptNo":1019014,"note":"","videoMemo":"","fangList":["桂枝加厚朴杏子汤"],"bieMing":""}}', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '2024-09-17T00:57:27.000Z', '15、太阳病。下之微喘者。表未解也。宜$f{桂枝加厚朴杏子汤}。', '2024-09-17T00:57:27.000Z', 1, NULL, 'q6u5siNb2hT', 'section', 'RQlEyXhbm4T');
